// 病句 코스 3 — tools/make_bingju.py 가 tools/bingju/c03.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[3]=[[{"o":["经过科研团队长达十余年的反复攻关，使我国自主研发的高温超导材料在临界温度上取得了重大突破。","这家汽车工厂的焊装车间已基本实现无人化，数百台机械臂昼夜不停地协同作业，定位精度可达零点一毫米。","蜜蜂通过一种特殊的“摇摆舞”向同伴传递蜜源的方向和距离，这一发现曾获得诺贝尔生理学或医学奖。","长江中下游平原河湖密布、土壤肥沃，自古以来便是我国重要的粮食产区，素有“鱼米之乡”的美誉。"],"a":0,"type":"주어 결여","why":"“经过…，使…” 때문에 문장에 주어가 없다. 经过는 개사라서 그 뒤의 말이 주어가 될 수 없다.","fix":"经过科研团队长达十余年的反复攻关，我国自主研发的高温超导材料在临界温度上取得了重大突破。","words":[["攻关","gōngguān","어려운 문제를 돌파하다"],["超导","chāodǎo","초전도"],["临界","línjiè","임계"],["鱼米之乡","yú mǐ zhī xiāng","물고기와 쌀이 풍부한 고장"],["焊装","hànzhuāng","용접 조립"],["机械臂","jīxièbì","로봇 팔"],["协同","xiétóng","협력하다"]],"tr":["연구팀이 십여 년에 걸쳐 거듭 난관을 돌파한 끝에, 우리나라가 독자 개발한 고온 초전도 소재가 임계 온도에서 큰 진전을 이루었다.","이 자동차 공장의 용접 조립 작업장은 거의 무인화되어, 수백 대의 로봇 팔이 밤낮없이 함께 작업하며 위치 정밀도는 0.1밀리미터에 이른다.","꿀벌은 특별한 ‘8자 춤’으로 동료에게 꿀이 있는 곳의 방향과 거리를 알려 주는데, 이 발견은 노벨 생리의학상을 받았다.","창장강 중하류 평야는 강과 호수가 빽빽하고 땅이 기름져 예로부터 중요한 곡창 지대였으며, ‘물고기와 쌀의 고장’으로 불려 왔다."],"ow":[[["攻关","gōngguān","어려운 문제를 돌파하다"],["自主","zìzhǔ","독자적으로"],["超导","chāodǎo","초전도"],["临界","línjiè","임계"],["突破","tūpò","돌파"]],[["焊装","hànzhuāng","용접 조립"],["车间","chējiān","작업장"],["机械臂","jīxièbì","로봇 팔"],["昼夜不停","zhòu yè bù tíng","밤낮없이"],["协同","xiétóng","협력하다"]],[["摇摆舞","yáobǎiwǔ","(꿀벌의) 8자 춤"],["蜜源","mìyuán","꿀이 나는 곳"],["传递","chuándì","전달하다"],["诺贝尔","Nuòbèi'ěr","노벨"]],[["密布","mìbù","빽빽하게 퍼져 있다"],["肥沃","féiwò","비옥하다"],["素有","sùyǒu","예로부터 지니다"],["鱼米之乡","yú mǐ zhī xiāng","물고기와 쌀이 풍부한 고장"],["美誉","měiyù","명성"]]]},{"o":["光在真空中每秒约传播三十万千米，这一数值被物理学家视为宇宙中信息传递速度的上限。","宋代瓷器以造型简洁、釉色含蓄著称，其中汝窑青瓷存世稀少，件件都是收藏家梦寐以求的珍品。","在新型显微成像技术的帮助下，让研究人员首次清晰地观察到了活细胞内蛋白质分子的运动轨迹。","长期处于高压状态的人，体内皮质醇水平往往偏高，这不仅会削弱免疫力，还可能导致睡眠质量下降。"],"a":2,"type":"주어 결여","why":"“在…的帮助下，让…” 때문에 주어가 없다. 研究人员이 让의 목적어가 되어 버려 ‘누가’ 관찰했는지가 문장에서 빠졌다.","fix":"在新型显微成像技术的帮助下，研究人员首次清晰地观察到了活细胞内蛋白质分子的运动轨迹。","words":[["显微","xiǎnwēi","현미(경)의"],["轨迹","guǐjì","궤적"],["釉色","yòusè","유약 빛깔"],["汝窑","Rǔyáo","여요(송대 명요)"],["梦寐以求","mèng mèi yǐ qiú","꿈에도 바라다"],["皮质醇","pízhìchún","코르티솔"],["削弱","xuēruò","약화시키다"]],"tr":["빛은 진공에서 1초에 약 30만 킬로미터를 가는데, 물리학자들은 이 값을 우주에서 정보가 전달될 수 있는 속도의 한계로 본다.","송나라 자기는 모양이 간결하고 유약 빛깔이 은은하기로 유명한데, 특히 여요 청자는 남은 것이 드물어 하나하나가 수집가들이 꿈에도 바라는 보물이다.","새로운 현미 영상 기술의 도움으로 연구진은 살아 있는 세포 속 단백질 분자가 움직이는 궤적을 처음으로 선명하게 관찰했다.","오랫동안 스트레스가 큰 상태에 있는 사람은 몸속 코르티솔 수치가 높은 편인데, 이는 면역력을 떨어뜨릴 뿐 아니라 수면의 질도 나빠지게 할 수 있다."],"ow":[[["真空","zhēnkōng","진공"],["数值","shùzhí","수치"],["视为","shìwéi","~로 보다"],["上限","shàngxiàn","상한"]],[["釉色","yòusè","유약 빛깔"],["含蓄","hánxù","은은하다"],["汝窑","Rǔyáo","여요"],["存世","cúnshì","세상에 남아 있다"],["梦寐以求","mèng mèi yǐ qiú","꿈에도 바라다"],["珍品","zhēnpǐn","진품"]],[["显微","xiǎnwēi","현미(경)의"],["成像","chéngxiàng","영상화"],["蛋白质","dànbáizhì","단백질"],["分子","fēnzǐ","분자"],["轨迹","guǐjì","궤적"]],[["皮质醇","pízhìchún","코르티솔"],["偏高","piāngāo","높은 편이다"],["削弱","xuēruò","약화시키다"],["免疫力","miǎnyìlì","면역력"]]]},{"o":["青藏高原平均海拔四千米以上，被誉为“世界屋脊”，孕育了长江、黄河、澜沧江等众多大江大河。","随着锂电池能量密度的大幅提升和生产成本的持续下降，使电动汽车车主的续航焦虑得到了明显缓解。","京剧脸谱的色彩各有寓意，一般来说，红色多象征忠勇正直，白色则常用来表现人物的奸诈多疑。","那位年过八旬的老匠人之所以至今仍坚持手工制作油纸伞，是因为他不愿看到这门手艺在自己手中失传。"],"a":1,"type":"주어 결여","why":"“随着…，使…” 때문에 주어가 없다. 随着로 시작한 앞부분은 주어가 될 수 없으니 使를 빼야 续航焦虑가 주어가 된다.","fix":"随着锂电池能量密度的大幅提升和生产成本的持续下降，电动汽车车主的续航焦虑得到了明显缓解。","words":[["孕育","yùnyù","낳아 기르다"],["锂电池","lǐdiànchí","리튬 전지"],["续航","xùháng","(한 번 충전으로) 계속 달리는 거리"],["脸谱","liǎnpǔ","경극 얼굴 분장"],["寓意","yùyì","담긴 뜻"],["奸诈","jiānzhà","간사하다"],["失传","shīchuán","전승이 끊기다"]],"tr":["칭짱고원은 평균 해발이 4천 미터가 넘어 ‘세계의 지붕’이라 불리며, 창장강·황허강·란창강 등 많은 큰 강이 이곳에서 시작된다.","리튬 전지의 에너지 밀도가 크게 높아지고 생산비가 계속 내려가면서, 전기차 운전자들이 주행 거리를 걱정하는 일이 눈에 띄게 줄었다.","경극 얼굴 분장의 색에는 저마다 뜻이 있어, 대개 붉은색은 충성과 용맹, 정직을 나타내고 흰색은 간사하고 의심 많은 인물을 표현할 때 쓴다.","여든이 넘은 그 장인이 지금도 손으로 기름종이 우산을 만드는 것은, 이 기술이 자기 대에서 끊기는 것을 보고 싶지 않기 때문이다."],"ow":[[["青藏高原","Qīngzàng Gāoyuán","칭짱고원"],["海拔","hǎibá","해발"],["屋脊","wūjǐ","지붕"],["孕育","yùnyù","낳아 기르다"],["澜沧江","Láncāng Jiāng","란창강"]],[["锂电池","lǐdiànchí","리튬 전지"],["密度","mìdù","밀도"],["续航","xùháng","(충전 한 번에) 계속 달리는 거리"],["焦虑","jiāolǜ","걱정, 불안"],["缓解","huǎnjiě","완화되다"]],[["脸谱","liǎnpǔ","경극 얼굴 분장"],["寓意","yùyì","담긴 뜻"],["忠勇","zhōngyǒng","충성스럽고 용맹하다"],["奸诈","jiānzhà","간사하다"],["多疑","duōyí","의심이 많다"]],[["八旬","bāxún","여든 살"],["匠人","jiàngrén","장인"],["油纸伞","yóuzhǐsǎn","기름종이 우산"],["手艺","shǒuyì","손기술"],["失传","shīchuán","전승이 끊기다"]]]},{"o":["我国古代的“二十四节气”精准反映了一年中气候与物候的变化，已被列入人类非物质文化遗产代表作名录。","人工智能在医学影像诊断领域进展迅速，部分算法识别早期肺癌的准确率已与资深医生不相上下。","这座横跨海峡的大桥全长五十余千米，建设者们克服了台风频发、海水腐蚀等重重困难才将其建成。","由于这位年轻作家对边疆生活的描写细腻而真实，令许多从未到过新疆的读者对那片土地心驰神往。"],"a":3,"type":"주어 결여","why":"“由于…，令…” 때문에 주어가 없다. 由于가 앞부분 전체를 원인 표현으로 만들어서 令의 주어가 사라졌다.","fix":"这位年轻作家对边疆生活的描写细腻而真实，令许多从未到过新疆的读者对那片土地心驰神往。","words":[["节气","jiéqì","절기"],["物候","wùhòu","계절에 따른 동식물의 변화"],["不相上下","bù xiāng shàng xià","막상막하"],["海峡","hǎixiá","해협"],["腐蚀","fǔshí","부식"],["边疆","biānjiāng","변경 지역"],["心驰神往","xīn chí shén wǎng","마음이 끌려 동경하다"]],"tr":["우리 옛 ‘24절기’는 한 해 동안의 기후와 동식물 변화를 정확히 반영하여, 인류무형문화유산 대표목록에 올랐다.","인공지능은 의료 영상 진단 분야에서 빠르게 발전해, 일부 알고리즘은 초기 폐암을 찾아내는 정확도가 경험 많은 의사와 막상막하다.","해협을 가로지르는 이 다리는 길이가 50여 킬로미터로, 건설자들은 잦은 태풍과 바닷물 부식 같은 숱한 어려움을 이겨 내고서야 다리를 완성했다.","이 젊은 작가가 변경 지역의 삶을 섬세하고 생생하게 그려 낸 덕분에, 신장에 가 본 적 없는 많은 독자가 그 땅을 동경하게 되었다."],"ow":[[["节气","jiéqì","절기"],["物候","wùhòu","계절에 따른 동식물 변화"],["非物质文化遗产","fēiwùzhì wénhuà yíchǎn","무형문화유산"],["名录","mínglù","목록"]],[["影像","yǐngxiàng","영상"],["诊断","zhěnduàn","진단"],["算法","suànfǎ","알고리즘"],["资深","zīshēn","경력이 많다"],["不相上下","bù xiāng shàng xià","막상막하"]],[["横跨","héngkuà","가로지르다"],["海峡","hǎixiá","해협"],["频发","pínfā","자주 발생하다"],["腐蚀","fǔshí","부식"],["重重","chóngchóng","겹겹이"]],[["边疆","biānjiāng","변경 지역"],["细腻","xìnì","섬세하다"],["新疆","Xīnjiāng","신장"],["心驰神往","xīn chí shén wǎng","마음이 끌려 동경하다"]]]},{"o":["为了尽快遏制外来物种互花米草在沿海滩涂的疯狂蔓延，当地有关部门近年来一系列的综合治理措施。","地球自转的速度并非恒定不变，潮汐摩擦等因素会使它极其缓慢地减慢，一天的长度因此在逐渐变长。","宣纸质地柔韧、洁白细密，而且不易被虫蛀，故有“纸寿千年”之说，历来深受书画家的青睐。","心理学研究表明，适度的焦虑能够提高人的注意力，但焦虑一旦过度，反而会妨碍正常水平的发挥。"],"a":0,"type":"술어 결여","why":"“为了…” 뒤에 주어(有关部门)와 목적어(措施)만 있고 “采取了” 같은 동사가 없다.","fix":"为了尽快遏制外来物种互花米草在沿海滩涂的疯狂蔓延，当地有关部门近年来采取了一系列综合治理措施。","words":[["遏制","èzhì","억제하다"],["滩涂","tāntú","갯벌"],["蔓延","mànyán","퍼지다"],["潮汐","cháoxī","조석, 밀물과 썰물"],["柔韧","róurèn","부드럽고 질기다"],["青睐","qīnglài","호감, 총애"],["妨碍","fáng'ài","방해하다"]],"tr":["외래종 갯끈풀이 해안 갯벌에서 마구 퍼지는 것을 하루빨리 막기 위해, 현지 관련 부서는 최근 몇 년 동안 일련의 종합 대책을 펼쳤다.","지구의 자전 속도는 늘 일정하지 않고 조석 마찰 같은 요인 때문에 아주 천천히 느려지며, 그래서 하루의 길이가 조금씩 길어지고 있다.","선지는 부드럽고 질기며 희고 촘촘한 데다 좀이 잘 슬지 않아 ‘종이 수명이 천 년’이라는 말이 있고, 예로부터 서화가들의 사랑을 받아 왔다.","심리학 연구에 따르면 적당한 불안은 주의력을 높여 주지만, 불안이 지나치면 오히려 평소 실력을 발휘하는 데 방해가 된다."],"ow":[[["遏制","èzhì","억제하다"],["互花米草","hùhuāmǐcǎo","갯끈풀"],["滩涂","tāntú","갯벌"],["蔓延","mànyán","퍼지다"],["治理","zhìlǐ","다스리다, 관리하다"]],[["自转","zìzhuàn","자전"],["恒定","héngdìng","일정하다"],["潮汐","cháoxī","조석"],["摩擦","mócā","마찰"]],[["宣纸","xuānzhǐ","선지(서화용 종이)"],["柔韧","róurèn","부드럽고 질기다"],["虫蛀","chóngzhù","좀이 슬다"],["历来","lìlái","예로부터"],["青睐","qīnglài","호감, 총애"]],[["适度","shìdù","적당하다"],["焦虑","jiāolǜ","불안"],["过度","guòdù","지나치다"],["妨碍","fáng'ài","방해하다"]]]},{"o":["火星表面呈现橘红色，是因为其土壤中含有大量氧化铁，因此人们常把它称为“红色星球”。","数控机床的操作人员不仅要熟悉机械原理，还要能够读懂复杂的加工图纸和程序代码。","针对近年来青少年近视率居高不下的问题，教育部门联合卫生部门在全国中小学广泛的视力健康普查。","量子计算机利用量子叠加原理进行运算，在某些特定问题上的计算速度有望远远超过传统计算机。"],"a":2,"type":"술어 결여","why":"“针对…” 뒤 본문에 “广泛的视力健康普查”라는 명사만 있고 “开展了” 같은 동사가 없다.","fix":"针对近年来青少年近视率居高不下的问题，教育部门联合卫生部门在全国中小学广泛开展了视力健康普查。","words":[["氧化铁","yǎnghuàtiě","산화철"],["居高不下","jū gāo bú xià","높은 채로 내려오지 않다"],["普查","pǔchá","전면 조사"],["叠加","diéjiā","중첩"],["数控机床","shùkòng jīchuáng","CNC 공작기계"],["图纸","túzhǐ","도면"]],"tr":["화성 표면이 주황빛을 띠는 것은 흙에 산화철이 많이 들어 있기 때문이며, 그래서 사람들은 화성을 ‘붉은 행성’이라 부른다.","CNC 공작기계를 다루는 사람은 기계 원리를 잘 알아야 할 뿐 아니라, 복잡한 가공 도면과 프로그램 코드도 읽을 줄 알아야 한다.","최근 청소년 근시율이 높은 채 내려오지 않는 문제에 대응해, 교육 당국은 보건 당국과 함께 전국 초중고에서 시력 건강 전면 조사를 폭넓게 벌였다.","양자 컴퓨터는 양자 중첩 원리로 계산하며, 일부 특정 문제에서는 계산 속도가 기존 컴퓨터를 훨씬 앞설 것으로 기대된다."],"ow":[[["火星","huǒxīng","화성"],["呈现","chéngxiàn","드러내다"],["橘红色","júhóngsè","주황색"],["氧化铁","yǎnghuàtiě","산화철"]],[["数控机床","shùkòng jīchuáng","CNC 공작기계"],["原理","yuánlǐ","원리"],["图纸","túzhǐ","도면"],["代码","dàimǎ","코드"]],[["针对","zhēnduì","~에 대응하여"],["近视","jìnshì","근시"],["居高不下","jū gāo bú xià","높은 채 내려오지 않다"],["普查","pǔchá","전면 조사"]],[["量子","liàngzǐ","양자"],["叠加","diéjiā","중첩"],["运算","yùnsuàn","연산하다"],["有望","yǒuwàng","~할 가망이 있다"]]]},{"o":["这家造船厂采用分段建造的方法，先在车间里造好船体的各个部分，再运到船坞中拼装成整船。","科学家发现，深海热泉附近虽然终年没有阳光，却生活着大量依靠化学能维持生命的微生物。","这位物理学家一生淡泊名利，晚年把全部积蓄捐给了家乡的学校，用于资助家境贫寒的学生。","博物馆把这批刚从南海沉船中打捞出水的宋代瓷器，经过文物专家长达半年的精心清理与修复。"],"a":3,"type":"술어 결여","why":"“把…瓷器” 뒤에 그 瓷器를 어떻게 했는지 말하는 동사가 없다. “经过…修复”는 과정만 말할 뿐이다.","fix":"博物馆把这批刚从南海沉船中打捞出水的宋代瓷器，经过文物专家长达半年的精心清理与修复后公开展出。","words":[["热泉","rèquán","(심해) 열수구"],["淡泊名利","dànbó mínglì","명예와 이익에 담담하다"],["积蓄","jīxù","저축한 돈"],["资助","zīzhù","경제적으로 돕다"],["打捞","dǎlāo","(물속에서) 건져 올리다"],["船坞","chuánwù","도크(선박 건조장)"],["拼装","pīnzhuāng","조립하다"]],"tr":["이 조선소는 블록 공법을 써서, 먼저 작업장에서 배의 각 부분을 만든 뒤 도크로 옮겨 배 한 척으로 조립한다.","과학자들은 심해 열수구 주변에는 일 년 내내 햇빛이 없는데도, 화학 에너지로 살아가는 미생물이 많이 산다는 것을 발견했다.","이 물리학자는 평생 명예와 이익에 담담했고, 말년에 모은 돈을 모두 고향 학교에 기부해 가난한 집 학생들을 돕는 데 쓰게 했다.","박물관은 남해 침몰선에서 막 건져 올린 이 송나라 자기들을, 문화재 전문가들이 반년에 걸쳐 정성껏 세척하고 복원하게 했다."],"ow":[[["造船厂","zàochuánchǎng","조선소"],["分段","fēnduàn","구간별로 나누다"],["车间","chējiān","작업장"],["船坞","chuánwù","도크"],["拼装","pīnzhuāng","조립하다"]],[["热泉","rèquán","(심해) 열수구"],["终年","zhōngnián","일 년 내내"],["维持","wéichí","유지하다"],["微生物","wēishēngwù","미생물"]],[["淡泊名利","dàn bó míng lì","명예와 이익에 담담하다"],["积蓄","jīxù","저축한 돈"],["资助","zīzhù","경제적으로 돕다"],["贫寒","pínhán","가난하다"]],[["沉船","chénchuán","침몰선"],["打捞","dǎlāo","건져 올리다"],["文物","wénwù","문화재"],["修复","xiūfù","복원하다"]]]},{"o":["黄山以奇松、怪石、云海、温泉“四绝”闻名于世，明代地理学家徐霞客曾两次登临并留下游记。","这项新技术大大提高了钙钛矿太阳能电池在弱光条件下将光能转化为电能的，有望加快其商业化进程。","这位翻译家毕生致力于中外文化交流，凭借深厚的学养将大量唐诗宋词译成英文，介绍给西方读者。","适量饮茶有助于提神醒脑，但空腹饮用浓茶容易刺激肠胃，严重时甚至可能引发心慌、头晕等“茶醉”症状。"],"a":1,"type":"목적어 결여","why":"“提高了…的” 뒤에 꾸밈을 받는 명사(效率)가 없다. 무엇을 높였는지가 빠졌다.","fix":"这项新技术大大提高了钙钛矿太阳能电池在弱光条件下将光能转化为电能的效率，有望加快其商业化进程。","words":[["闻名于世","wén míng yú shì","세상에 이름나다"],["徐霞客","Xú Xiákè","서하객(명대 지리학자)"],["登临","dēnglín","높은 곳에 올라 둘러보다"],["钙钛矿","gàitàikuàng","페로브스카이트"],["学养","xuéyǎng","학식과 교양"],["提神醒脑","tí shén xǐng nǎo","정신을 맑게 하다"]],"tr":["황산은 기이한 소나무, 괴석, 운해, 온천의 ‘네 가지 절경’으로 세계에 이름났으며, 명나라 지리학자 서하객은 두 번 올라 기행문을 남겼다.","이 신기술은 약한 빛에서 페로브스카이트 태양전지가 빛을 전기로 바꾸는 효율을 크게 높여, 상용화를 앞당길 것으로 기대된다.","이 번역가는 평생 중국과 외국의 문화 교류에 힘썼고, 깊은 학식으로 수많은 당시와 송사를 영어로 옮겨 서양 독자에게 소개했다.","차를 적당히 마시면 정신이 맑아지지만, 빈속에 진한 차를 마시면 위장이 자극받아 심하면 가슴 두근거림이나 어지럼 같은 ‘차 취함’ 증상이 생길 수 있다."],"ow":[[["黄山","Huáng Shān","황산"],["云海","yúnhǎi","운해"],["闻名于世","wén míng yú shì","세상에 이름나다"],["徐霞客","Xú Xiákè","서하객"],["登临","dēnglín","높은 곳에 올라 보다"]],[["钙钛矿","gàitàikuàng","페로브스카이트"],["转化","zhuǎnhuà","바꾸다"],["有望","yǒuwàng","~할 가망이 있다"],["商业化","shāngyèhuà","상용화"]],[["毕生","bìshēng","평생"],["致力","zhìlì","힘쓰다"],["凭借","píngjiè","~에 기대어"],["学养","xuéyǎng","학식과 교양"],["唐诗宋词","Táng shī Sòng cí","당시와 송사"]],[["提神醒脑","tí shén xǐng nǎo","정신을 맑게 하다"],["空腹","kōngfù","빈속"],["肠胃","chángwèi","위장"],["心慌","xīnhuāng","가슴이 두근거리다"],["头晕","tóuyūn","어지럽다"]]]},{"o":["人工智能翻译软件的日益普及，为不同语言背景的人们进行无障碍交流提供了前所未有的。","鲸鱼虽然终生生活在海洋中，却并不属于鱼类，而是用肺呼吸、胎生哺乳的哺乳动物。","北宋画家张择端的《清明上河图》生动描绘了汴京城内外的繁华景象，具有极高的历史价值。","这家创立于清朝末年的老字号坚持选用上等原料、沿用传统工艺，其产品的口碑百余年来经久不衰。"],"a":0,"type":"목적어 결여","why":"“提供了前所未有的” 뒤에 명사(便利)가 없어 무엇을 제공했는지 알 수 없다.","fix":"人工智能翻译软件的日益普及，为不同语言背景的人们进行无障碍交流提供了前所未有的便利。","words":[["前所未有","qián suǒ wèi yǒu","전례가 없다"],["胎生","tāishēng","태생(새끼를 낳음)"],["哺乳","bǔrǔ","젖을 먹이다"],["汴京","Biànjīng","변경(북송의 수도)"],["老字号","lǎozìhao","오래된 전통 상점"],["经久不衰","jīng jiǔ bù shuāi","오래도록 시들지 않다"]],"tr":["인공지능 번역 앱이 날로 널리 쓰이면서, 언어 배경이 다른 사람들이 막힘없이 소통하는 데 전례 없는 편리함을 주고 있다.","고래는 평생 바다에서 살지만 어류가 아니라, 폐로 숨 쉬고 새끼를 낳아 젖을 먹이는 포유동물이다.","북송 화가 장택단의 「청명상하도」는 변경 성 안팎의 번화한 모습을 생생히 그려 역사적 가치가 매우 높다.","청나라 말에 세워진 이 오래된 가게는 최상급 재료와 전통 공정을 고집해, 백여 년 동안 제품의 평판이 식지 않았다."],"ow":[[["日益","rìyì","날로"],["普及","pǔjí","보급되다"],["障碍","zhàng'ài","장애"],["前所未有","qián suǒ wèi yǒu","전례 없다"]],[["鲸鱼","jīngyú","고래"],["终生","zhōngshēng","평생"],["胎生","tāishēng","새끼를 낳음"],["哺乳动物","bǔrǔ dòngwù","포유동물"]],[["张择端","Zhāng Zéduān","장택단"],["清明上河图","Qīngmíng Shànghé Tú","청명상하도"],["描绘","miáohuì","묘사하다"],["汴京","Biànjīng","변경(북송 수도)"],["繁华","fánhuá","번화하다"]],[["老字号","lǎozìhao","오래된 전통 상점"],["沿用","yányòng","그대로 쓰다"],["工艺","gōngyì","공예, 공정"],["口碑","kǒubēi","평판"],["经久不衰","jīng jiǔ bù shuāi","오래도록 시들지 않다"]]]},{"o":["化学家门捷列夫根据元素性质的周期性变化编制出元素周期表，并据此预言了几种当时尚未发现的元素。","竹子虽然外形高大挺拔，但在植物学上却属于禾本科，与小麦、水稻等粮食作物是“近亲”。","这次国际学术研讨会吸引了来自三十多个国家和地区、长期从事古代丝绸之路历史与考古研究的。","医学研究发现，一个人如果长期睡眠不足，不仅记忆力会明显减退，情绪也容易变得烦躁不安。"],"a":2,"type":"목적어 결여","why":"“吸引了…的” 뒤에 꾸밈을 받는 명사(学者)가 없어 누가 왔는지가 빠졌다.","fix":"这次国际学术研讨会吸引了来自三十多个国家和地区、长期从事古代丝绸之路历史与考古研究的学者。","words":[["门捷列夫","Ménjiélièfū","멘델레예프"],["周期表","zhōuqībiǎo","주기율표"],["挺拔","tǐngbá","곧고 높이 솟다"],["禾本科","héběnkē","벼과"],["研讨会","yántǎohuì","학술 토론회"],["考古","kǎogǔ","고고학"],["烦躁","fánzào","초조하고 짜증 나다"]],"tr":["화학자 멘델레예프는 원소 성질의 주기적 변화에 따라 주기율표를 만들고, 이를 근거로 당시 아직 발견되지 않은 몇몇 원소를 예언했다.","대나무는 겉보기에 크고 곧게 솟아 있지만 식물학적으로는 벼과에 속해, 밀·벼 같은 곡물과 ‘가까운 친척’이다.","이번 국제 학술 토론회에는 30여 개 나라와 지역에서 고대 실크로드의 역사와 고고학을 오래 연구해 온 학자들이 모였다.","의학 연구에 따르면 오랫동안 잠이 부족한 사람은 기억력이 눈에 띄게 떨어질 뿐 아니라 감정도 쉽게 초조하고 불안해진다."],"ow":[[["门捷列夫","Ménjiélièfū","멘델레예프"],["周期性","zhōuqīxìng","주기성"],["编制","biānzhì","만들다, 편성하다"],["周期表","zhōuqībiǎo","주기율표"],["尚未","shàngwèi","아직 ~하지 않다"]],[["挺拔","tǐngbá","곧고 높이 솟다"],["植物学","zhíwùxué","식물학"],["禾本科","héběnkē","벼과"],["近亲","jìnqīn","가까운 친척"]],[["研讨会","yántǎohuì","학술 토론회"],["丝绸之路","Sīchóu zhī Lù","실크로드"],["考古","kǎogǔ","고고학"],["从事","cóngshì","종사하다"]],[["减退","jiǎntuì","감퇴하다"],["烦躁不安","fán zào bù ān","초조하고 불안하다"],["睡眠","shuìmián","수면"]]]}],[{"o":["危险化学品运输车辆必须按照指定的路线和时段行驶，驾驶员和押运员也都要持有专门的从业资格证。","据天文学家估算，银河系中大约有一千亿到四千亿颗左右的恒星，太阳只是其中极为普通的一员。","珊瑚礁仅占海洋面积的极小部分，却为约四分之一的海洋鱼类提供了栖息地，有“海洋中的热带雨林”之称。","他年轻时曾在西北边疆支教多年，那段艰苦而充实的经历，深深影响了他此后的人生选择。"],"a":1,"type":"어림수 중복","why":"“大约”와 “左右”가 둘 다 ‘대략’이라는 뜻이라 한 숫자에 겹쳐 썼다.","fix":"据天文学家估算，银河系中大约有一千亿到四千亿颗恒星，太阳只是其中极为普通的一员。","words":[["估算","gūsuàn","어림 계산하다"],["恒星","héngxīng","항성"],["珊瑚礁","shānhújiāo","산호초"],["栖息地","qīxīdì","서식지"],["支教","zhījiào","(낙후 지역에 가서) 교육 봉사를 하다"],["押运","yāyùn","호송하다"],["从业","cóngyè","업무에 종사하다"]],"tr":["위험 화학물질 운송 차량은 정해진 경로와 시간대에만 다녀야 하며, 운전기사와 호송원도 모두 전문 종사 자격증을 갖춰야 한다.","천문학자들의 추산에 따르면 은하계에는 대략 1천억에서 4천억 개의 항성이 있고, 태양은 그중 아주 평범한 하나일 뿐이다.","산호초는 바다 면적의 아주 작은 부분일 뿐이지만 바닷물고기의 약 4분의 1에게 서식지를 제공해 ‘바다의 열대우림’이라 불린다.","그는 젊은 시절 서북 변경에서 여러 해 교육 봉사를 했고, 힘들지만 알찼던 그 경험은 이후 인생의 선택에 깊은 영향을 주었다."],"ow":[[["危险化学品","wēixiǎn huàxuépǐn","위험 화학물질"],["指定","zhǐdìng","지정하다"],["押运员","yāyùnyuán","호송원"],["从业","cóngyè","업무에 종사하다"],["资格证","zīgézhèng","자격증"]],[["估算","gūsuàn","어림 계산하다"],["银河系","yínhéxì","은하계"],["恒星","héngxīng","항성"]],[["珊瑚礁","shānhújiāo","산호초"],["栖息地","qīxīdì","서식지"],["热带雨林","rèdài yǔlín","열대우림"]],[["边疆","biānjiāng","변경 지역"],["支教","zhījiào","교육 봉사를 하다"],["充实","chōngshí","알차다"]]]},{"o":["铁在潮湿的空气中容易与氧气、水发生反应生成铁锈，因此铁制品表面常涂上油漆加以保护。","研究人员发现，将这种抗菌涂层用于医院门把手后，其表面的细菌数量在两小时内减少了九成以上。","这位导演的新作取材于真实事件，上映后迅速引发了社会各界对留守儿童心理健康问题的广泛讨论。","这段古城墙始建于明洪武年间，距今已有六百余年左右的历史，是我国现存最完整的古代城垣之一。"],"a":3,"type":"어림수 중복","why":"“六百余年”의 “余”가 이미 ‘~남짓’이라는 어림수인데 “左右”를 또 붙였다.","fix":"这段古城墙始建于明洪武年间，距今已有六百余年的历史，是我国现存最完整的古代城垣之一。","words":[["铁锈","tiěxiù","쇠녹"],["涂层","túcéng","코팅층"],["取材","qǔcái","소재를 얻다"],["留守儿童","liúshǒu értóng","부모가 외지로 떠나 남겨진 아이"],["洪武","Hóngwǔ","홍무(명 태조의 연호)"],["城垣","chéngyuán","성벽"]],"tr":["쇠는 습한 공기 속에서 산소, 물과 쉽게 반응해 녹이 슬기 때문에 쇠로 만든 물건 표면에는 흔히 페인트를 칠해 보호한다.","연구진은 이 항균 코팅을 병원 문손잡이에 쓰자 두 시간 안에 표면 세균이 90% 넘게 줄었다는 것을 발견했다.","이 감독의 신작은 실제 사건에서 소재를 얻어, 개봉하자마자 남겨진 아이들의 마음 건강 문제에 대해 사회 각계의 폭넓은 논의를 불러일으켰다.","이 옛 성벽은 명나라 홍무 연간에 처음 지어져 6백여 년의 역사를 지녔으며, 우리나라에 남은 옛 성벽 가운데 가장 온전한 것 중 하나다."],"ow":[[["潮湿","cháoshī","습하다"],["氧气","yǎngqì","산소"],["铁锈","tiěxiù","쇠녹"],["油漆","yóuqī","페인트"],["加以","jiāyǐ","~을 가하다"]],[["抗菌","kàngjūn","항균"],["涂层","túcéng","코팅층"],["门把手","ménbǎshou","문손잡이"],["细菌","xìjūn","세균"]],[["取材","qǔcái","소재를 얻다"],["上映","shàngyìng","상영하다"],["留守儿童","liúshǒu értóng","부모가 떠나 남겨진 아이"],["各界","gèjiè","각계"]],[["城墙","chéngqiáng","성벽"],["始建","shǐjiàn","처음 짓다"],["洪武","Hóngwǔ","홍무(명 태조 연호)"],["城垣","chéngyuán","성벽"]]]},{"o":["由于城乡之间教育资源的分配差距悬殊很大，部分偏远地区的学校长期面临师资匮乏的困境。","指南针的前身是战国时期的“司南”，后来经由阿拉伯人传入欧洲，为远洋航海提供了重要条件。","大熊猫的祖先原本以肉类为食，在漫长的进化过程中，它们的食性逐渐转变为以竹子为主。","新研制的仿生机器人模仿了壁虎脚掌的微观结构，能够在光滑的玻璃幕墙上自如地攀爬。"],"a":0,"type":"뜻 중복","why":"“悬殊”가 이미 ‘차이가 매우 크다’는 뜻인데 “很大”를 또 붙였다.","fix":"由于城乡之间教育资源的分配差距悬殊，部分偏远地区的学校长期面临师资匮乏的困境。","words":[["悬殊","xuánshū","차이가 매우 크다"],["匮乏","kuìfá","부족하다"],["司南","sīnán","사남(초기 나침반)"],["食性","shíxìng","먹이 습성"],["仿生","fǎngshēng","생물을 본뜬"],["壁虎","bìhǔ","도마뱀붙이"],["攀爬","pānpá","기어오르다"]],"tr":["도시와 농촌 사이에 교육 자원의 배분 격차가 너무 커서, 일부 외딴 지역 학교는 오랫동안 교사가 모자라는 어려움을 겪고 있다.","나침반의 전신은 전국시대의 ‘사남’이며, 이후 아랍인을 거쳐 유럽에 전해져 먼바다 항해에 중요한 조건을 마련해 주었다.","대왕판다의 조상은 원래 고기를 먹었지만, 오랜 진화 과정에서 먹이 습성이 점차 대나무 위주로 바뀌었다.","새로 개발한 생체 모방 로봇은 도마뱀붙이 발바닥의 미세 구조를 본떠, 매끄러운 유리 외벽도 자유롭게 기어오를 수 있다."],"ow":[[["悬殊","xuánshū","차이가 매우 크다"],["偏远","piānyuǎn","외지다"],["师资","shīzī","교사 인력"],["匮乏","kuìfá","부족하다"],["困境","kùnjìng","곤경"]],[["指南针","zhǐnánzhēn","나침반"],["前身","qiánshēn","전신"],["司南","sīnán","사남(초기 나침반)"],["航海","hánghǎi","항해"]],[["祖先","zǔxiān","조상"],["漫长","màncháng","길다"],["进化","jìnhuà","진화"],["食性","shíxìng","먹이 습성"]],[["仿生","fǎngshēng","생물을 본뜬"],["壁虎","bìhǔ","도마뱀붙이"],["微观","wēiguān","미시적"],["幕墙","mùqiáng","(건물) 외벽"],["攀爬","pānpá","기어오르다"]]]},{"o":["在精密仪器制造车间里，工人必须穿戴防静电工作服，以免静电击穿微小的电子元件。","喜马拉雅山脉至今仍在以每年数毫米的速度缓慢抬升，这是印度板块持续向北挤压欧亚板块的结果。","研究团队开展这项长期追踪实验，其目的是为了弄清微塑料进入人体后究竟会在哪些器官中积聚。","他之所以放弃大城市的高薪工作回到家乡，是因为想用自己所学的农业技术帮助乡亲们致富。"],"a":2,"type":"뜻 중복","why":"“目的是”와 “为了”가 둘 다 목적을 나타내어 뜻이 겹친다.","fix":"研究团队开展这项长期追踪实验，其目的是弄清微塑料进入人体后究竟会在哪些器官中积聚。","words":[["板块","bǎnkuài","(지각의) 판"],["挤压","jǐyā","밀어붙이다"],["微塑料","wēisùliào","미세플라스틱"],["积聚","jījù","쌓이다"],["致富","zhìfù","부유해지다"],["静电","jìngdiàn","정전기"],["击穿","jīchuān","(전기로) 뚫어 망가뜨리다"],["元件","yuánjiàn","부품, 소자"]],"tr":["정밀 기기 제조 작업장에서 작업자는 반드시 정전기 방지 작업복을 입어, 정전기가 작은 전자 부품을 망가뜨리지 않게 해야 한다.","히말라야산맥은 지금도 해마다 몇 밀리미터씩 천천히 솟아오르고 있는데, 이는 인도판이 유라시아판을 계속 북쪽으로 밀어붙인 결과다.","연구팀이 이 장기 추적 실험을 하는 목적은 미세플라스틱이 몸에 들어온 뒤 어느 장기에 쌓이는지를 밝히는 데 있다.","그가 대도시의 높은 연봉을 버리고 고향으로 돌아온 것은, 배운 농업 기술로 마을 사람들이 잘살게 돕고 싶었기 때문이다."],"ow":[[["精密仪器","jīngmì yíqì","정밀 기기"],["车间","chējiān","작업장"],["静电","jìngdiàn","정전기"],["击穿","jīchuān","(전기로) 뚫어 망가뜨리다"],["元件","yuánjiàn","부품, 소자"]],[["喜马拉雅","Xǐmǎlāyǎ","히말라야"],["山脉","shānmài","산맥"],["板块","bǎnkuài","(지각의) 판"],["挤压","jǐyā","밀어붙이다"]],[["追踪","zhuīzōng","추적하다"],["微塑料","wēisùliào","미세플라스틱"],["器官","qìguān","장기"],["积聚","jījù","쌓이다"]],[["之所以","zhīsuǒyǐ","~한 까닭은"],["乡亲","xiāngqīn","고향 사람들"],["致富","zhìfù","부유해지다"]]]},{"o":["金属的导电性能与其内部自由电子的数量和运动状况密切相关，银、铜、金的导电性尤为出色。","杜甫一生忧国忧民，他的诗歌真实记录了唐朝由盛转衰的社会面貌，因而被后人誉为“诗史”。","实验结果显示，每天坚持三十分钟中等强度运动的老年人，患认知障碍的风险明显低于很少运动的同龄人。","这片湿地的候鸟数量锐减，主要原因是周边大规模填海造地、鸟类栖息环境遭到严重破坏的缘故。"],"a":3,"type":"뜻 중복","why":"“原因是”와 “…的缘故”가 둘 다 이유를 말하는 표현이라 겹친다.","fix":"这片湿地的候鸟数量锐减，主要原因是周边大规模填海造地、鸟类栖息环境遭到严重破坏。","words":[["导电","dǎodiàn","전기가 통하다"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["认知障碍","rènzhī zhàng'ài","인지 장애"],["锐减","ruìjiǎn","급감하다"],["填海造地","tián hǎi zào dì","바다를 메워 땅을 만들다"],["缘故","yuángù","까닭"]],"tr":["금속의 전기 전도 성능은 내부 자유 전자의 수와 움직임에 크게 좌우되며, 은·구리·금의 전도성이 특히 뛰어나다.","두보는 평생 나라와 백성을 걱정했고, 그의 시는 당나라가 번성에서 쇠퇴로 넘어가는 사회 모습을 사실대로 기록해 후대에 ‘시로 쓴 역사’라 불린다.","실험 결과, 날마다 30분씩 중간 강도 운동을 꾸준히 한 노인은 운동을 거의 안 하는 또래보다 인지 장애에 걸릴 위험이 확연히 낮았다.","이 습지의 철새가 크게 줄어든 주된 이유는 주변에서 대규모로 바다를 메워 땅을 만들면서 새들의 서식 환경이 심하게 훼손되었기 때문이다."],"ow":[[["导电","dǎodiàn","전기가 통하다"],["电子","diànzǐ","전자"],["尤为","yóuwéi","특히"]],[["杜甫","Dù Fǔ","두보"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["由盛转衰","yóu shèng zhuǎn shuāi","번성에서 쇠퇴로 바뀌다"],["面貌","miànmào","모습"]],[["强度","qiángdù","강도"],["认知障碍","rènzhī zhàng'ài","인지 장애"],["同龄人","tónglíngrén","또래"]],[["湿地","shīdì","습지"],["候鸟","hòuniǎo","철새"],["锐减","ruìjiǎn","급감하다"],["填海造地","tián hǎi zào dì","바다를 메워 땅을 만들다"],["栖息","qīxī","서식하다"],["缘故","yuángù","까닭"]]]},{"o":["光合作用是绿色植物利用光能，把二氧化碳和水转化为储存着能量的有机物并释放出氧气的过程。","这位老教授在去世之前的生前，曾将毕生收藏的古籍善本全部无偿捐赠给了国家图书馆。","这家老牌水泥厂淘汰了大批高耗能的立窑，转而生产附加值更高的特种水泥，重新赢得了市场。","智能手机在给人们带来便利的同时，也让不少人患上了“信息焦虑”，一刻不看手机就心神不宁。"],"a":1,"type":"뜻 중복","why":"“生前”이 곧 ‘죽기 전’이라는 뜻인데 “去世之前”을 또 써서 뜻이 겹친다.","fix":"这位老教授生前曾将毕生收藏的古籍善本全部无偿捐赠给了国家图书馆。","words":[["光合作用","guānghé zuòyòng","광합성"],["毕生","bìshēng","평생"],["古籍善本","gǔjí shànběn","귀중한 고서"],["无偿","wúcháng","무상으로"],["心神不宁","xīn shén bù níng","마음이 불안하다"],["附加值","fùjiāzhí","부가가치"],["立窑","lìyáo","수직 가마(시멘트 소성로)"]],"tr":["광합성은 녹색 식물이 빛 에너지를 이용해 이산화탄소와 물을 에너지가 저장된 유기물로 바꾸고 산소를 내놓는 과정이다.","이 노교수는 살아 있을 때 평생 모은 귀중한 고서를 모두 국가도서관에 무상으로 기증했다.","이 오래된 시멘트 공장은 에너지를 많이 쓰는 수직 가마를 대거 없애고 부가가치가 더 높은 특수 시멘트를 만들기 시작해 시장을 되찾았다.","스마트폰은 사람들에게 편리함을 주는 동시에 많은 이를 ‘정보 불안’에 빠뜨려, 잠시라도 휴대폰을 안 보면 마음이 불안해지게 했다."],"ow":[[["光合作用","guānghé zuòyòng","광합성"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["储存","chǔcún","저장하다"],["有机物","yǒujīwù","유기물"],["释放","shìfàng","내놓다"]],[["去世","qùshì","세상을 떠나다"],["毕生","bìshēng","평생"],["古籍善本","gǔjí shànběn","귀중한 고서"],["无偿","wúcháng","무상으로"],["捐赠","juānzèng","기증하다"]],[["老牌","lǎopái","오래된 유명 업체의"],["淘汰","táotài","도태시키다"],["立窑","lìyáo","수직 가마(시멘트 소성로)"],["附加值","fùjiāzhí","부가가치"]],[["便利","biànlì","편리함"],["焦虑","jiāolǜ","불안"],["心神不宁","xīn shén bù níng","마음이 불안하다"]]]},{"o":["据考证，我国早在三千多年前的商代就已能够冶炼青铜，并铸造出了后母戊鼎这样的国之重器。","研究发现，有些植物在遭受虫害时会释放出特殊的化学物质，以吸引害虫的天敌前来“帮忙”。","凡是参观过三星堆遗址的游客，无不都被那些造型奇特、神秘莫测的青铜面具所深深震撼。","新能源汽车的普及离不开充电设施的完善，否则即使车辆性能再好，消费者也难免心存顾虑。"],"a":2,"type":"기타 군더더기","why":"“无不”가 이미 ‘모두 ~하다’는 뜻인데 “都”를 또 붙였다.","fix":"凡是参观过三星堆遗址的游客，无不被那些造型奇特、神秘莫测的青铜面具所深深震撼。","words":[["冶炼","yěliàn","제련하다"],["后母戊鼎","Hòumǔwù dǐng","후모무정(상대 청동 솥)"],["天敌","tiāndí","천적"],["三星堆","Sānxīngduī","삼성퇴 유적"],["神秘莫测","shén mì mò cè","신비로워 헤아릴 수 없다"],["震撼","zhènhàn","크게 감동시키다"],["心存顾虑","xīn cún gù lǜ","걱정을 품다"]],"tr":["고증에 따르면 우리나라는 이미 3천여 년 전 상나라 때 청동을 제련할 수 있었고, 후모무정 같은 나라의 귀중한 그릇을 주조해 냈다.","연구에 따르면 어떤 식물은 해충에게 공격받으면 특별한 화학 물질을 내뿜어 해충의 천적을 불러들여 ‘도움’을 받는다.","싼싱두이 유적을 본 관람객은 하나같이 기이하고 신비로운 청동 가면에 깊은 충격을 받는다.","신에너지 차가 널리 쓰이려면 충전 시설이 잘 갖춰져야 하며, 그렇지 않으면 차 성능이 아무리 좋아도 소비자는 걱정을 품기 마련이다."],"ow":[[["考证","kǎozhèng","고증"],["冶炼","yěliàn","제련하다"],["铸造","zhùzào","주조하다"],["后母戊鼎","Hòumǔwù dǐng","후모무정"]],[["遭受","zāoshòu","당하다"],["虫害","chónghài","병충해"],["释放","shìfàng","내뿜다"],["天敌","tiāndí","천적"]],[["凡是","fánshì","무릇"],["三星堆","Sānxīngduī","싼싱두이 유적"],["无不","wúbù","~하지 않는 것이 없다"],["神秘莫测","shén mì mò cè","신비로워 헤아릴 수 없다"],["震撼","zhènhàn","크게 감동시키다"]],[["新能源","xīnnéngyuán","신에너지"],["设施","shèshī","시설"],["难免","nánmiǎn","~하기 마련이다"],["心存顾虑","xīn cún gù lǜ","걱정을 품다"]]]},{"o":["考古人员对这批出土于马王堆汉墓的丝织品进行了细致的加以清理和修复，使其重现了两千多年前的光彩。","嫦娥四号探测器于2019年1月在月球背面成功着陆，实现了人类探测器首次在月球背面软着陆。","成年人体内的水分约占体重的百分之六十，即使只是轻度脱水，也可能出现注意力下降、反应迟缓等症状。","这家出版社推出的古籍数字化平台，使读者足不出户就能在线查阅数万种珍贵的古代典籍。"],"a":0,"type":"기타 군더더기","why":"“进行了”와 “加以”가 둘 다 뒤의 동작(清理、修复)을 이끄는 말이라 하나만 있어야 한다.","fix":"考古人员对这批出土于马王堆汉墓的丝织品进行了细致的清理和修复，使其重现了两千多年前的光彩。","words":[["马王堆","Mǎwángduī","마왕퇴(한대 무덤)"],["丝织品","sīzhīpǐn","견직물"],["探测器","tàncèqì","탐사선"],["软着陆","ruǎnzhuólù","연착륙"],["脱水","tuōshuǐ","탈수"],["迟缓","chíhuǎn","느리다"],["足不出户","zú bù chū hù","집 밖에 나가지 않다"]],"tr":["고고학자들은 마왕퇴 한나라 무덤에서 나온 이 견직물들을 꼼꼼히 세척하고 복원해, 2천여 년 전의 빛깔을 되살렸다.","창어 4호 탐사선은 2019년 1월 달 뒷면에 착륙해, 인류의 탐사선이 처음으로 달 뒷면에 연착륙하는 일을 이루었다.","성인 몸의 수분은 체중의 약 60%를 차지하며, 가벼운 탈수만으로도 주의력이 떨어지고 반응이 느려지는 증상이 나타날 수 있다.","이 출판사가 내놓은 고서 디지털 플랫폼 덕분에 독자들은 집 밖에 나가지 않고도 수만 종의 귀한 옛 문헌을 온라인으로 찾아볼 수 있다."],"ow":[[["马王堆","Mǎwángduī","마왕퇴"],["出土","chūtǔ","출토되다"],["丝织品","sīzhīpǐn","견직물"],["加以","jiāyǐ","~을 가하다"],["修复","xiūfù","복원하다"]],[["嫦娥","Cháng'é","창어(달 탐사선 이름)"],["探测器","tàncèqì","탐사선"],["着陆","zhuólù","착륙하다"],["软着陆","ruǎnzhuólù","연착륙"]],[["脱水","tuōshuǐ","탈수"],["迟缓","chíhuǎn","느리다"],["症状","zhèngzhuàng","증상"]],[["数字化","shùzìhuà","디지털화"],["足不出户","zú bù chū hù","집 밖에 나가지 않다"],["查阅","cháyuè","찾아 읽다"],["典籍","diǎnjí","고전 문헌"]]]},{"o":["电脑键盘的字母排列之所以看似杂乱无章，据说是为了避免早期打字机的连杆在快速敲击时相互卡住。","刺绣是中国优秀的民族传统工艺之一，其中苏绣、湘绣、蜀绣和粤绣被合称为“四大名绣”。","风力发电不消耗燃料、不排放温室气体，但其发电量受风速影响较大，稳定性不如火力发电。","这一地区的风沙逐年减弱，原因是因为当地数十年如一日地坚持退耕还林、植树种草。"],"a":3,"type":"기타 군더더기","why":"“原因是” 뒤에 “因为”를 또 써서 이유 표현이 두 번 들어갔다.","fix":"这一地区的风沙逐年减弱，原因是当地数十年如一日地坚持退耕还林、植树种草。","words":[["杂乱无章","zá luàn wú zhāng","어수선하고 질서가 없다"],["连杆","liángǎn","(타자기의) 활자대"],["刺绣","cìxiù","자수"],["温室气体","wēnshì qìtǐ","온실가스"],["数十年如一日","shù shí nián rú yí rì","수십 년을 하루같이"],["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"]],"tr":["컴퓨터 자판의 글자 배열이 어수선해 보이는 것은 초기 타자기의 활자대가 빨리 칠 때 서로 엉키지 않게 하려던 것이라고 한다.","자수는 중국의 뛰어난 전통 공예 가운데 하나로, 그중 쑤저우·후난·쓰촨·광둥의 자수를 묶어 ‘4대 명수’라 부른다.","풍력 발전은 연료를 쓰지 않고 온실가스도 내뿜지 않지만, 발전량이 풍속에 크게 좌우되어 화력 발전보다 안정성이 떨어진다.","이 지역의 모래바람이 해마다 약해진 것은 현지에서 수십 년을 하루같이 경작지를 숲으로 되돌리고 나무와 풀을 심어 왔기 때문이다."],"ow":[[["键盘","jiànpán","자판"],["杂乱无章","zá luàn wú zhāng","어수선하고 질서가 없다"],["连杆","liángǎn","(타자기의) 활자대"],["敲击","qiāojī","두드리다"]],[["刺绣","cìxiù","자수"],["工艺","gōngyì","공예"],["苏绣","sūxiù","쑤저우 자수"],["合称","héchēng","묶어 부르다"]],[["风力发电","fēnglì fādiàn","풍력 발전"],["燃料","ránliào","연료"],["温室气体","wēnshì qìtǐ","온실가스"],["火力发电","huǒlì fādiàn","화력 발전"]],[["风沙","fēngshā","모래바람"],["数十年如一日","shù shí nián rú yí rì","수십 년을 하루같이"],["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"]]]},{"o":["古希腊学者埃拉托色尼曾通过测量两地正午日影的角度差，相当准确地推算出了地球的周长。","这位作家擅长从平凡琐碎的市井生活中发掘诗意，作品语言质朴，却耐人寻味。","这家研究所六十多年来一直始终扎根沙漠边缘，培育出了数十种适合在流动沙丘上生长的固沙植物。","医生建议，成年人每天的食盐摄入量最好不超过五克，这对预防高血压、减轻肾脏负担都大有裨益。"],"a":2,"type":"기타 군더더기","why":"“一直”와 “始终”이 둘 다 ‘처음부터 끝까지 계속’이라는 뜻이라 하나는 빼야 한다.","fix":"这家研究所六十多年来一直扎根沙漠边缘，培育出了数十种适合在流动沙丘上生长的固沙植物。","words":[["埃拉托色尼","Āilātuōsèní","에라토스테네스"],["推算","tuīsuàn","추산하다"],["市井","shìjǐng","저잣거리, 서민 사회"],["耐人寻味","nài rén xún wèi","음미할 만하다"],["扎根","zhāgēn","뿌리내리다"],["固沙","gùshā","모래를 고정하다"],["裨益","bìyì","이로움"]],"tr":["고대 그리스 학자 에라토스테네스는 두 곳의 정오 그림자 각도 차를 재어 지구 둘레를 꽤 정확히 계산해 냈다.","이 작가는 평범하고 자잘한 서민의 삶에서 시적인 정취를 찾아내는 데 뛰어나, 작품의 말은 소박하지만 곱씹을수록 맛이 있다.","이 연구소는 60여 년 동안 줄곧 사막 가장자리에 뿌리내리고, 움직이는 모래 언덕에서 자랄 수 있는 모래 고정 식물 수십 종을 길러 냈다.","의사들은 성인이 하루 소금 섭취량을 5그램 넘지 않게 하는 것이 좋다고 하는데, 이는 고혈압 예방과 콩팥 부담을 줄이는 데 큰 도움이 된다."],"ow":[[["埃拉托色尼","Āilātuōsèní","에라토스테네스"],["日影","rìyǐng","해 그림자"],["推算","tuīsuàn","추산하다"],["周长","zhōucháng","둘레"]],[["擅长","shàncháng","뛰어나다"],["琐碎","suǒsuì","자질구레하다"],["市井","shìjǐng","서민 사회"],["质朴","zhìpǔ","소박하다"],["耐人寻味","nài rén xún wèi","음미할 만하다"]],[["扎根","zhāgēn","뿌리내리다"],["培育","péiyù","길러 내다"],["沙丘","shāqiū","모래 언덕"],["固沙","gùshā","모래를 고정하다"]],[["摄入量","shèrùliàng","섭취량"],["高血压","gāoxuèyā","고혈압"],["肾脏","shènzàng","콩팥"],["大有裨益","dà yǒu bì yì","큰 도움이 되다"]]]}],[{"o":["这次大规模的城市更新工程，显著提高了老城区的整体面貌，居民的生活条件也随之大为改善。","恐龙在约六千六百万年前突然大规模灭绝，目前多数科学家认为，这与一颗小行星撞击地球密切相关。","茶圣陆羽所著的《茶经》是世界上第一部茶学专著，系统总结了唐代以前种茶、制茶和饮茶的经验。","孩子在成长过程中难免会犯错，家长与其一味地指责，不如耐心引导他们从错误中吸取教训。"],"a":0,"type":"동사–목적어","why":"“面貌”(모습)는 “提高”(높이다)와 어울리지 않는다. 모습은 “改变”하거나 “改善”한다.","fix":"这次大规模的城市更新工程，显著改变了老城区的整体面貌，居民的生活条件也随之大为改善。","words":[["面貌","miànmào","모습, 상태"],["灭绝","mièjué","멸종하다"],["陆羽","Lù Yǔ","육우(당대 다성)"],["专著","zhuānzhù","전문 저서"],["一味","yíwèi","무턱대고"],["吸取教训","xīqǔ jiàoxùn","교훈을 얻다"]],"tr":["이번 대규모 도시 재생 사업은 옛 도심의 전체 모습을 눈에 띄게 바꾸었고, 주민들의 생활 여건도 덩달아 크게 나아졌다.","공룡은 약 6,600만 년 전에 갑자기 대규모로 멸종했는데, 지금 대부분의 과학자는 이것이 소행성 충돌과 깊이 관련되어 있다고 본다.","다성 육우가 쓴 「다경」은 세계 최초의 차 전문 서적으로, 당나라 이전의 차 재배, 제조, 음용 경험을 체계적으로 정리했다.","아이는 자라면서 실수하기 마련이니, 부모는 무턱대고 나무라기보다 아이가 실수에서 교훈을 얻도록 차분히 이끌어 주는 편이 낫다."],"ow":[[["更新","gēngxīn","재생, 새롭게 하다"],["显著","xiǎnzhù","두드러지게"],["面貌","miànmào","모습"],["随之","suízhī","그에 따라"]],[["恐龙","kǒnglóng","공룡"],["灭绝","mièjué","멸종하다"],["小行星","xiǎoxíngxīng","소행성"],["撞击","zhuàngjī","충돌하다"]],[["茶圣","cháshèng","다성(차의 성인)"],["陆羽","Lù Yǔ","육우"],["茶经","Chájīng","다경"],["专著","zhuānzhù","전문 저서"],["系统","xìtǒng","체계적으로"]],[["难免","nánmiǎn","~하기 마련이다"],["与其","yǔqí","~하기보다는"],["一味","yíwèi","무턱대고"],["引导","yǐndǎo","이끌다"],["吸取教训","xīqǔ jiàoxùn","교훈을 얻다"]]]},{"o":["物体在月球上的重量只有在地球上的六分之一左右，这是因为月球的引力比地球小得多。","昆曲发源于元末明初的江苏昆山一带，以唱腔婉转细腻著称，被誉为“百戏之祖”。","专家指出，要从根本上减少电信诈骗案件，关键是要健全公众的防范意识，同时完善相关法律法规。","这位登山家曾三次登顶珠穆朗玛峰，在他看来，攀登的意义不在于征服高山，而在于挑战自我。"],"a":2,"type":"동사–목적어","why":"“健全”(제도를 갖추다)은 “意识”(의식)와 어울리지 않는다. 의식은 “增强”(높이다)한다.","fix":"专家指出，要从根本上减少电信诈骗案件，关键是要增强公众的防范意识，同时完善相关法律法规。","words":[["引力","yǐnlì","인력"],["昆曲","kūnqǔ","곤곡(중국 전통극)"],["婉转","wǎnzhuǎn","(곡조가) 부드럽고 아름답다"],["电信诈骗","diànxìn zhàpiàn","전화·인터넷 사기"],["健全","jiànquán","(제도를) 완비하다"],["防范","fángfàn","방비하다"]],"tr":["물체의 무게는 달에서 지구에서의 약 6분의 1밖에 되지 않는데, 이는 달의 인력이 지구보다 훨씬 작기 때문이다.","곤곡은 원나라 말 명나라 초 장쑤성 쿤산 일대에서 생겨났고, 가락이 부드럽고 섬세하기로 이름나 ‘모든 극의 시조’라 불린다.","전문가들은 전화·인터넷 사기를 근본적으로 줄이려면 대중의 경계심을 높이는 동시에 관련 법규를 보완하는 것이 핵심이라고 지적했다.","이 산악인은 에베레스트 정상에 세 번 올랐는데, 그가 보기에 등반의 의미는 산을 정복하는 데 있지 않고 자신에게 도전하는 데 있다."],"ow":[[["物体","wùtǐ","물체"],["引力","yǐnlì","인력"]],[["昆曲","kūnqǔ","곤곡"],["发源","fāyuán","발원하다"],["唱腔","chàngqiāng","노래 가락"],["婉转","wǎnzhuǎn","부드럽고 아름답다"],["著称","zhùchēng","이름나다"]],[["电信诈骗","diànxìn zhàpiàn","전화·인터넷 사기"],["健全","jiànquán","완비하다"],["防范","fángfàn","방비하다"],["法规","fǎguī","법규"]],[["登顶","dēngdǐng","정상에 오르다"],["珠穆朗玛峰","Zhūmùlǎngmǎ Fēng","에베레스트산"],["攀登","pāndēng","등반하다"],["征服","zhēngfú","정복하다"]]]},{"o":["浩瀚的宇宙中存在着大量看不见的“暗物质”，它们不发光也不反射光，只能通过引力效应被间接探测到。","这对双胞胎姐妹虽然长相酷似，性格却截然不同：姐姐沉稳内敛，妹妹则活泼外向。","中医认为，人体的健康状况与四季的气候变化息息相关，因此养生应当顺应自然、因时而异。","每一位年满十八周岁的公民，都可以依法履行自己的选举权和被选举权，这是宪法赋予公民的基本政治权利。"],"a":3,"type":"동사–목적어","why":"“权”(권리)는 “履行”(의무를 이행하다)과 어울리지 않는다. 권리는 “行使”(행사하다)한다.","fix":"每一位年满十八周岁的公民，都可以依法行使自己的选举权和被选举权，这是宪法赋予公民的基本政治权利。","words":[["浩瀚","hàohàn","광대하다"],["暗物质","ànwùzhì","암흑물질"],["酷似","kùsì","매우 닮다"],["截然不同","jié rán bù tóng","완전히 다르다"],["内敛","nèiliǎn","차분하고 드러내지 않다"],["履行","lǚxíng","(의무를) 이행하다"],["行使","xíngshǐ","(권리를) 행사하다"]],"tr":["광활한 우주에는 눈에 보이지 않는 ‘암흑물질’이 많이 있는데, 빛을 내지도 반사하지도 않아 중력 효과로만 간접적으로 찾아낼 수 있다.","이 쌍둥이 자매는 생김새가 꼭 닮았지만 성격은 딴판이다. 언니는 차분하고 속을 잘 드러내지 않고, 동생은 활발하고 외향적이다.","한의학에서는 몸의 건강이 사계절의 기후 변화와 밀접하게 이어져 있다고 보아, 건강 관리도 자연을 따르고 때에 맞게 달리 해야 한다고 한다.","만 18세가 된 모든 시민은 법에 따라 선거권과 피선거권을 행사할 수 있으며, 이는 헌법이 시민에게 준 기본적인 정치 권리다."],"ow":[[["浩瀚","hàohàn","광대하다"],["暗物质","àn wùzhì","암흑물질"],["反射","fǎnshè","반사하다"],["探测","tàncè","탐지하다"]],[["双胞胎","shuāngbāotāi","쌍둥이"],["酷似","kùsì","매우 닮다"],["截然不同","jié rán bù tóng","완전히 다르다"],["沉稳","chénwěn","침착하다"],["内敛","nèiliǎn","드러내지 않다"]],[["中医","zhōngyī","한의학"],["息息相关","xī xī xiāng guān","밀접하게 관련되다"],["养生","yǎngshēng","양생, 건강 관리"],["顺应","shùnyìng","따르다"]],[["履行","lǚxíng","이행하다"],["选举权","xuǎnjǔquán","선거권"],["宪法","xiànfǎ","헌법"],["赋予","fùyǔ","부여하다"]]]},{"o":["研究人员利用基因编辑技术培育出一种抗病能力极强的番茄，其产量比普通品种高出约三成。","经过三年的生态修复，这片曾经寸草不生的废弃矿区，植被覆盖率已经变得十分茂盛。","随着工业机器人的大规模应用，喷漆工、搬运工等传统工种的岗位需求正在发生深刻的变化。","电影《流浪地球》讲述了人类在太阳即将毁灭之际，推动地球离开太阳系寻找新家园的故事。"],"a":1,"type":"주어–술어","why":"“覆盖率”(덮인 비율)는 숫자라서 “茂盛”(무성하다)할 수 없다. 비율은 “提高”하고, 무성한 것은 식물 자체다.","fix":"经过三年的生态修复，这片曾经寸草不生的废弃矿区，植被覆盖率已经大幅提高。","words":[["基因编辑","jīyīn biānjí","유전자 편집"],["番茄","fānqié","토마토"],["寸草不生","cùn cǎo bù shēng","풀 한 포기 나지 않다"],["植被","zhíbèi","식생"],["工种","gōngzhǒng","직종"],["喷漆","pēnqī","도장(페인트 분사)"]],"tr":["연구진은 유전자 편집 기술로 병에 매우 강한 토마토를 길러 냈는데, 수확량이 일반 품종보다 약 30% 많다.","3년 동안 생태를 복원한 끝에, 한때 풀 한 포기 나지 않던 이 폐광 지역은 식물이 이미 무성하게 우거졌다.","공업용 로봇이 대규모로 쓰이면서 도장공, 운반공 같은 전통 직종의 일자리 수요가 크게 바뀌고 있다.","영화 「유랑지구」는 태양이 곧 소멸하려는 때에 인류가 지구를 밀어 태양계를 벗어나 새 보금자리를 찾아가는 이야기를 그렸다."],"ow":[[["基因编辑","jīyīn biānjí","유전자 편집"],["培育","péiyù","길러 내다"],["番茄","fānqié","토마토"],["品种","pǐnzhǒng","품종"]],[["生态","shēngtài","생태"],["寸草不生","cùn cǎo bù shēng","풀 한 포기 나지 않다"],["植被","zhíbèi","식생"],["覆盖率","fùgàilǜ","피복률"],["茂盛","màoshèng","무성하다"]],[["工业机器人","gōngyè jīqìrén","산업용 로봇"],["喷漆","pēnqī","도장(페인트 분사)"],["搬运","bānyùn","운반하다"],["工种","gōngzhǒng","직종"],["岗位","gǎngwèi","일자리"]],[["流浪地球","Liúlàng Dìqiú","유랑지구(영화)"],["毁灭","huǐmiè","소멸하다"],["太阳系","tàiyángxì","태양계"],["家园","jiāyuán","보금자리"]]]},{"o":["声音在不同介质中的传播速度并不相同，一般来说，在固体中最快，在液体中次之，在气体中最慢。","诸葛亮一生“鞠躬尽瘁，死而后已”，他的智慧与忠诚，千百年来一直为后人所传颂。","吐鲁番盆地深居内陆、地势低洼，夏季的气温常常异常炎热，被人们形象地称为“火洲”。","人工智能写作工具虽然能在短时间内生成大量文字，但其内容的准确性仍需要人工仔细核对。"],"a":2,"type":"주어–술어","why":"“气温”(기온)은 숫자라서 “炎热”(무덥다)와 어울리지 않는다. 기온은 “高”하고, 무더운 것은 날씨다.","fix":"吐鲁番盆地深居内陆、地势低洼，夏季常常异常炎热，被人们形象地称为“火洲”。","words":[["介质","jièzhì","매질"],["鞠躬尽瘁","jū gōng jìn cuì","몸과 마음을 다 바치다"],["传颂","chuánsòng","기리며 전하다"],["盆地","péndì","분지"],["低洼","dīwā","움푹 낮다"],["核对","héduì","대조 확인하다"]],"tr":["소리가 전해지는 속도는 매질마다 다른데, 대체로 고체에서 가장 빠르고 액체가 그다음이며 기체에서 가장 느리다.","제갈량은 평생 ‘몸과 마음을 다 바치다가 죽어서야 멈추었고’, 그의 지혜와 충성은 천여 년 동안 후세 사람들에게 칭송받아 왔다.","투루판 분지는 내륙 깊숙이 있고 지대가 낮아 여름이면 몹시 무더워서, 사람들이 실감 나게 ‘불의 땅’이라고 부른다.","인공지능 글쓰기 도구는 짧은 시간에 많은 글을 만들어 낼 수 있지만, 그 내용이 정확한지는 여전히 사람이 꼼꼼히 확인해야 한다."],"ow":[[["介质","jièzhì","매질"],["固体","gùtǐ","고체"],["液体","yètǐ","액체"],["次之","cìzhī","그다음이다"]],[["诸葛亮","Zhūgě Liàng","제갈량"],["鞠躬尽瘁","jū gōng jìn cuì","몸과 마음을 다 바치다"],["死而后已","sǐ ér hòu yǐ","죽어서야 그치다"],["传颂","chuánsòng","기리며 전하다"]],[["吐鲁番","Tǔlǔfān","투루판"],["盆地","péndì","분지"],["低洼","dīwā","움푹 낮다"],["炎热","yánrè","무덥다"],["火洲","huǒzhōu","불의 땅"]],[["生成","shēngchéng","생성하다"],["准确性","zhǔnquèxìng","정확성"],["核对","héduì","대조 확인하다"]]]},{"o":["微波炉加热食物的原理，是利用微波使食物中的水分子剧烈振动、相互摩擦而产生热量。","这家濒临倒闭的小工厂，在年轻厂长的带领下转型生产环保材料，短短几年便扭亏为盈。","自古以来，黄河既哺育了两岸的华夏儿女，也曾因频繁泛滥而给沿岸百姓带来深重的灾难。","明代宋应星所著的《天工开物》的问世，是我国古代一部全面记述农业和手工业生产技术的百科全书。"],"a":3,"type":"주어–목적어","why":"주어가 “问世”(세상에 나온 일)인데 목적어는 “百科全书”(책)라서 ‘나온 일 = 책’이 되어 맞지 않는다.","fix":"明代宋应星所著的《天工开物》，是我国古代一部全面记述农业和手工业生产技术的百科全书。","words":[["微波炉","wēibōlú","전자레인지"],["濒临","bīnlín","(위기에) 직면하다"],["扭亏为盈","niǔ kuī wéi yíng","적자를 흑자로 돌리다"],["哺育","bǔyù","기르다"],["泛滥","fànlàn","범람하다"],["问世","wènshì","세상에 나오다"],["天工开物","Tiāngōng Kāiwù","천공개물(명대 기술서)"]],"tr":["전자레인지가 음식을 데우는 원리는 마이크로파로 음식 속 물 분자를 세게 떨게 하여 서로 마찰하면서 열이 나게 하는 것이다.","문 닫기 직전이던 이 작은 공장은 젊은 공장장의 지휘 아래 친환경 소재 생산으로 바꾸어 불과 몇 년 만에 적자를 흑자로 돌렸다.","예로부터 황허강은 양쪽 기슭의 중국 사람들을 길러 왔지만, 자주 범람하여 강가 백성에게 깊은 재난을 안기기도 했다.","명나라 송응성이 쓴 「천공개물」은 농업과 수공업의 생산 기술을 두루 기록한 우리나라 옛 백과사전이다."],"ow":[[["微波炉","wēibōlú","전자레인지"],["原理","yuánlǐ","원리"],["分子","fēnzǐ","분자"],["振动","zhèndòng","진동하다"],["摩擦","mócā","마찰하다"]],[["濒临","bīnlín","(위기에) 직면하다"],["倒闭","dǎobì","도산하다"],["转型","zhuǎnxíng","전환하다"],["扭亏为盈","niǔ kuī wéi yíng","적자를 흑자로 돌리다"]],[["哺育","bǔyù","기르다"],["华夏","Huáxià","중화, 중국"],["泛滥","fànlàn","범람하다"],["深重","shēnzhòng","심각하다"]],[["宋应星","Sòng Yìngxīng","송응성"],["天工开物","Tiāngōng Kāiwù","천공개물"],["问世","wènshì","세상에 나오다"],["记述","jìshù","기술하다"],["百科全书","bǎikē quánshū","백과사전"]]]},{"o":["世界上第一台通用电子计算机“埃尼阿克”的体积，是一个重达三十吨、占地约一百七十平方米的庞然大物。","考古发现表明，我国是世界上最早栽培水稻的国家之一，河姆渡遗址出土的炭化稻谷距今已有约七千年。","他虽然从未接受过专业的绘画训练，但凭借对色彩的敏锐感知，他的作品屡次在国际大赛中获奖。","适度的挫折未必不是一件好事，它可以帮助年轻人认清自身的不足，磨炼坚韧的意志。"],"a":0,"type":"주어–목적어","why":"주어가 “体积”(부피)인데 목적어는 “庞然大物”(거대한 물체)라서 ‘부피 = 물체’가 되어 맞지 않는다.","fix":"世界上第一台通用电子计算机“埃尼阿克”，是一个重达三十吨、占地约一百七十平方米的庞然大物。","words":[["庞然大物","páng rán dà wù","거대한 물체"],["栽培","zāipéi","재배하다"],["河姆渡","Hémǔdù","하모도 유적"],["炭化","tànhuà","탄화"],["敏锐","mǐnruì","예민하다"],["屡次","lǚcì","여러 번"],["坚韧","jiānrèn","강인하다"]],"tr":["세계 최초의 범용 전자 계산기 ‘에니악’은 무게 30톤에 바닥 면적이 약 170제곱미터인 거대한 기계였다.","고고학 발견에 따르면 우리나라는 세계에서 가장 먼저 벼를 재배한 나라 가운데 하나로, 하모도 유적에서 나온 탄화한 볍씨는 약 7천 년 전 것이다.","그는 정식으로 그림을 배운 적이 없지만 색에 대한 예민한 감각 덕분에 그의 작품은 국제 대회에서 여러 번 상을 받았다.","적당한 좌절이 꼭 나쁜 일만은 아니다. 젊은이가 자신의 부족함을 똑똑히 알고 굳센 의지를 기르는 데 도움이 될 수 있다."],"ow":[[["通用","tōngyòng","범용"],["计算机","jìsuànjī","컴퓨터"],["埃尼阿克","Āiní'ākè","에니악"],["庞然大物","páng rán dà wù","거대한 물체"]],[["栽培","zāipéi","재배하다"],["河姆渡","Hémǔdù","하모도"],["遗址","yízhǐ","유적"],["炭化","tànhuà","탄화"],["稻谷","dàogǔ","볍씨, 벼"]],[["凭借","píngjiè","~에 기대어"],["敏锐","mǐnruì","예민하다"],["感知","gǎnzhī","감지, 감각"],["屡次","lǚcì","여러 번"]],[["挫折","cuòzhé","좌절"],["未必","wèibì","꼭 ~한 것은 아니다"],["磨炼","móliàn","단련하다"],["坚韧","jiānrèn","강인하다"]]]},{"o":["秦岭—淮河一线是我国重要的地理分界线，其南北两侧在气候、植被和农业生产方式上差异显著。","这次探测器能否在预定区域精准着陆，取决于导航控制系统在最后几分钟里能够准确判断地形。","明朝航海家郑和曾率领庞大船队七下西洋，最远到达了东非沿岸，比哥伦布发现美洲早了八十余年。","不少年轻人热衷于在社交平台上分享生活点滴，却很少意识到其中可能隐藏着个人信息泄露的风险。"],"a":1,"type":"양면–한면","why":"앞은 “能否”(될지 안 될지) 두 쪽을 말하는데 뒤는 “能够”(된다) 한쪽만 말해 서로 맞지 않는다.","fix":"这次探测器能否在预定区域精准着陆，取决于导航控制系统在最后几分钟里能否准确判断地形。","words":[["分界线","fēnjièxiàn","경계선"],["显著","xiǎnzhù","두드러지다"],["着陆","zhuólù","착륙하다"],["郑和","Zhèng Hé","정화(명대 항해가)"],["西洋","Xīyáng","서양(남해 서쪽 바다)"],["热衷","rèzhōng","열중하다"],["泄露","xièlòu","누설되다"]],"tr":["친링산맥과 화이허강을 잇는 선은 우리나라의 중요한 지리 경계선으로, 그 남북은 기후, 식생, 농사 방식에서 차이가 뚜렷하다.","이번에 탐사선이 정해진 구역에 정확히 착륙할 수 있을지는 마지막 몇 분 동안 항법 제어 시스템이 지형을 정확히 판단하느냐에 달려 있다.","명나라 항해가 정화는 거대한 선단을 이끌고 일곱 차례 서양으로 나아가 멀리 동아프리카 해안까지 이르렀는데, 이는 콜럼버스의 아메리카 발견보다 80여 년 앞선다.","적잖은 젊은이가 소셜 미디어에 일상을 나누는 데 열중하지만, 그 속에 개인 정보가 새어 나갈 위험이 숨어 있다는 것은 거의 깨닫지 못한다."],"ow":[[["秦岭","Qínlǐng","친링산맥"],["淮河","Huái Hé","화이허강"],["分界线","fēnjièxiàn","경계선"],["植被","zhíbèi","식생"],["显著","xiǎnzhù","두드러지다"]],[["探测器","tàncèqì","탐사선"],["着陆","zhuólù","착륙하다"],["取决于","qǔjué yú","~에 달려 있다"],["导航","dǎoháng","항법"]],[["郑和","Zhèng Hé","정화"],["船队","chuánduì","선단"],["西洋","Xīyáng","서양(남해 서쪽 바다)"],["哥伦布","Gēlúnbù","콜럼버스"]],[["热衷","rèzhōng","열중하다"],["点滴","diǎndī","소소한 일들"],["隐藏","yǐncáng","숨기다"],["泄露","xièlòu","누설되다"]]]},{"o":["水在四摄氏度时密度最大，因此冬天湖面结冰后，湖底的水温通常仍能保持在四摄氏度左右，鱼类得以安然越冬。","叉车司机属于特种设备作业人员，必须经过专门培训并取得操作证书后才能上岗。","睡眠质量的高低，直接决定了一个人第二天能精力充沛地投入工作和学习。","这款翻译耳机支持四十多种语言的实时互译，让出国旅行的人们不再为语言不通而发愁。"],"a":2,"type":"양면–한면","why":"앞은 “高低”(높고 낮음) 두 쪽인데 뒤는 “能精力充沛”(힘이 넘칠 수 있다) 한쪽만 말해 맞지 않는다.","fix":"睡眠质量的高低，直接决定了一个人第二天能否精力充沛地投入工作和学习。","words":[["密度","mìdù","밀도"],["越冬","yuèdōng","겨울을 나다"],["精力充沛","jīng lì chōng pèi","원기가 왕성하다"],["互译","hùyì","서로 번역하다"],["叉车","chāchē","지게차"],["上岗","shànggǎng","일자리에 투입되다"]],"tr":["물은 섭씨 4도에서 밀도가 가장 커서, 겨울에 호수 표면이 얼어도 바닥의 물은 대개 4도 안팎을 유지해 물고기가 무사히 겨울을 날 수 있다.","지게차 운전사는 특수 장비 작업자에 속해, 반드시 전문 교육을 받고 조작 자격증을 딴 뒤에야 일을 시작할 수 있다.","수면의 질이 좋은지 나쁜지가, 다음 날 힘차게 일과 공부에 몰두할 수 있는지를 곧바로 좌우한다.","이 번역 이어폰은 40여 개 언어의 실시간 상호 통역을 지원해, 해외여행을 하는 사람들이 더는 말이 안 통해 걱정하지 않게 해 준다."],"ow":[[["摄氏度","shèshìdù","섭씨 온도"],["密度","mìdù","밀도"],["安然","ānrán","무사히"],["越冬","yuèdōng","겨울을 나다"]],[["叉车","chāchē","지게차"],["特种设备","tèzhǒng shèbèi","특수 장비"],["证书","zhèngshū","증서, 자격증"],["上岗","shànggǎng","일자리에 투입되다"]],[["睡眠","shuìmián","수면"],["精力充沛","jīng lì chōng pèi","원기가 왕성하다"],["投入","tóurù","몰두하다"]],[["耳机","ěrjī","이어폰"],["实时","shíshí","실시간"],["互译","hùyì","서로 번역하다"],["发愁","fāchóu","걱정하다"]]]},{"o":["布达拉宫始建于公元七世纪，依山而建、气势恢宏，是藏族古建筑艺术的杰出代表。","塑料在自然环境中极难降解，一个普通的塑料袋可能需要数百年才能被完全分解。","这位钢琴家五岁开始学琴，十二岁便登上维也纳金色大厅的舞台，被乐评人称为“天才少年”。","这所中学开设了机器人编程、无人机操控等课程，旨在激发学生的科学兴趣和动手能力。"],"a":3,"type":"목적어 여럿 중 일부","why":"“激发”(불러일으키다)는 “兴趣”(흥미)와는 맞지만 “动手能力”(손으로 만드는 능력)와는 맞지 않는다. 능력은 “培养”한다.","fix":"这所中学开设了机器人编程、无人机操控等课程，旨在激发学生的科学兴趣，培养他们的动手能力。","words":[["恢宏","huīhóng","웅장하다"],["降解","jiàngjiě","(자연적으로) 분해되다"],["维也纳","Wéiyěnà","빈(오스트리아)"],["编程","biānchéng","프로그래밍"],["旨在","zhǐzài","~을 목적으로 하다"],["激发","jīfā","불러일으키다"]],"tr":["포탈라궁은 7세기에 처음 지어졌고 산을 따라 웅장하게 세워져, 티베트족 옛 건축 예술의 빼어난 대표작이다.","플라스틱은 자연에서 매우 잘 분해되지 않아, 평범한 비닐봉지 하나가 완전히 분해되기까지 수백 년이 걸릴 수 있다.","이 피아니스트는 다섯 살에 피아노를 시작해 열두 살에 빈 황금홀 무대에 올랐고, 음악 평론가들에게 ‘천재 소년’이라 불렸다.","이 중학교는 로봇 프로그래밍, 드론 조종 같은 과목을 열어 학생들의 과학적 흥미와 손으로 만드는 능력을 키우려 한다."],"ow":[[["布达拉宫","Bùdálā Gōng","포탈라궁"],["依山而建","yī shān ér jiàn","산을 따라 짓다"],["气势恢宏","qì shì huī hóng","기세가 웅장하다"],["藏族","Zàngzú","티베트족"],["杰出","jiéchū","뛰어나다"]],[["塑料","sùliào","플라스틱"],["降解","jiàngjiě","(자연적으로) 분해되다"],["分解","fēnjiě","분해되다"]],[["维也纳","Wéiyěnà","빈(오스트리아)"],["金色大厅","Jīnsè Dàtīng","황금홀"],["乐评人","yuèpíngrén","음악 평론가"]],[["编程","biānchéng","프로그래밍"],["无人机","wúrénjī","드론"],["操控","cāokòng","조종하다"],["旨在","zhǐzài","~을 목적으로 하다"],["激发","jīfā","불러일으키다"]]]}],[{"o":["专家提醒，对于老旧小区中电线私拉乱接等火灾隐患，相关部门及时应该进行排查和整改。","竹简是纸张普及之前我国最主要的书写材料，许多先秦典籍正是靠它才得以流传至今。","超导体在电阻降为零时几乎不会损耗电能，因而在电力传输、医疗成像等领域有着广阔的应用前景。","那场突如其来的暴雨虽然打乱了运动会的日程安排，却丝毫没有影响同学们参赛的热情。"],"a":0,"type":"부사·능원동사 위치","why":"능원동사 “应该”는 부사 “及时” 앞에 와야 한다. “及时应该”는 순서가 뒤바뀌었다.","fix":"专家提醒，对于老旧小区中电线私拉乱接等火灾隐患，相关部门应该及时进行排查和整改。","words":[["隐患","yǐnhuàn","잠재된 위험"],["整改","zhěnggǎi","바로잡아 고치다"],["竹简","zhújiǎn","죽간"],["典籍","diǎnjí","고전 문헌"],["损耗","sǔnhào","손실"],["突如其来","tū rú qí lái","갑자기 닥치다"]],"tr":["전문가들은 오래된 주택 단지에서 전선을 함부로 끌어다 연결하는 등의 화재 위험에 대해 관련 부서가 제때 점검하고 바로잡아야 한다고 당부했다.","죽간은 종이가 널리 쓰이기 전 우리나라의 가장 주된 필기 재료였고, 많은 선진 시대 고전이 바로 그 덕분에 오늘날까지 전해질 수 있었다.","초전도체는 전기 저항이 0이 되면 전기 에너지를 거의 잃지 않아, 전력 송전과 의료 영상 같은 분야에서 쓰임새가 넓을 것으로 보인다.","갑작스러운 폭우가 운동회 일정을 흐트러뜨렸지만, 학생들의 경기 참가 열기에는 조금도 영향을 주지 않았다."],"ow":[[["隐患","yǐnhuàn","잠재된 위험"],["私拉乱接","sī lā luàn jiē","(전선을) 함부로 끌어다 잇다"],["排查","páichá","하나하나 점검하다"],["整改","zhěnggǎi","바로잡아 고치다"]],[["竹简","zhújiǎn","죽간"],["普及","pǔjí","보급되다"],["先秦","Xiān Qín","선진(진나라 이전) 시대"],["典籍","diǎnjí","고전 문헌"],["得以","déyǐ","~할 수 있게 되다"]],[["超导体","chāodǎotǐ","초전도체"],["电阻","diànzǔ","전기 저항"],["损耗","sǔnhào","손실"],["前景","qiánjǐng","전망"]],[["突如其来","tū rú qí lái","갑자기 닥치다"],["打乱","dǎluàn","흐트러뜨리다"],["丝毫","sīháo","조금도"]]]},{"o":["据说牛顿是受到苹果落地的启发，才开始思考物体之间相互吸引的规律，并最终提出了万有引力定律。","这部描写敦煌守护者的话剧不仅在国内多次巡演，在海外曾也引起过不小的轰动。","我国古代的计时工具有日晷、漏刻等，其中漏刻是利用滴水的多少来计量时间的。","适当晒太阳有助于人体合成维生素D，从而促进钙的吸收，但夏季正午时分应尽量避免长时间暴晒。"],"a":1,"type":"부사·능원동사 위치","why":"부사가 겹칠 때 “也”가 “曾” 앞에 와야 한다. “曾也”는 순서가 틀렸다.","fix":"这部描写敦煌守护者的话剧不仅在国内多次巡演，在海外也曾引起过不小的轰动。","words":[["万有引力","wànyǒu yǐnlì","만유인력"],["巡演","xúnyǎn","순회공연하다"],["轰动","hōngdòng","센세이션을 일으키다"],["日晷","rìguǐ","해시계"],["漏刻","lòukè","물시계"],["暴晒","bàoshài","뙤약볕에 쬐다"]],"tr":["뉴턴은 사과가 떨어지는 것을 보고 영감을 얻어 물체끼리 서로 끌어당기는 법칙을 생각하기 시작했고, 마침내 만유인력 법칙을 내놓았다고 한다.","둔황을 지키는 사람들을 그린 이 연극은 국내에서 여러 차례 순회공연했을 뿐 아니라, 해외에서도 한때 적잖은 화제를 모았다.","우리나라 옛 시간 측정 도구에는 해시계와 물시계 등이 있는데, 그중 물시계는 떨어진 물의 양으로 시간을 쟀다.","햇볕을 적당히 쬐면 몸이 비타민 D를 만드는 데 도움이 되어 칼슘 흡수를 돕지만, 여름 한낮에는 오래 뙤약볕을 쬐는 일을 되도록 피해야 한다."],"ow":[[["牛顿","Niúdùn","뉴턴"],["启发","qǐfā","영감, 깨우침"],["万有引力","wànyǒu yǐnlì","만유인력"],["定律","dìnglǜ","법칙"]],[["敦煌","Dūnhuáng","둔황"],["话剧","huàjù","연극"],["巡演","xúnyǎn","순회공연하다"],["轰动","hōngdòng","센세이션을 일으키다"]],[["计时","jìshí","시간을 재다"],["日晷","rìguǐ","해시계"],["漏刻","lòukè","물시계"],["计量","jìliàng","측정하다"]],[["维生素","wéishēngsù","비타민"],["合成","héchéng","합성하다"],["正午","zhèngwǔ","정오"],["暴晒","bàoshài","뙤약볕에 쬐다"]]]},{"o":["秦始皇陵兵马俑坑出土的陶俑形态各异、栩栩如生，几乎找不到两张完全相同的面孔。","由于纳米材料的比表面积极大，其物理和化学性质往往与同种物质的宏观形态存在明显差异。","那位老科学家晚年移居海外，自从三十多年前离开故乡后，就没有再也回去过，这成了他一生的遗憾。","无论科技如何进步，读书带给人的那份宁静与思考，都是任何电子设备所难以取代的。"],"a":2,"type":"부정사 위치","why":"“再也”는 부정사 “没有” 앞에 와야 한다. “没有再也”는 순서가 뒤바뀌었다.","fix":"那位老科学家晚年移居海外，自从三十多年前离开故乡后，就再也没有回去过，这成了他一生的遗憾。","words":[["兵马俑","bīngmǎyǒng","병마용"],["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"],["纳米","nàmǐ","나노미터"],["宏观","hóngguān","거시적"],["移居","yíjū","이주하다"],["取代","qǔdài","대신하다"]],"tr":["진시황릉 병마용 갱에서 나온 도용들은 모습이 제각각이고 살아 있는 듯 생생해, 똑같은 얼굴 둘을 찾기 어렵다.","나노 소재는 비표면적이 매우 커서, 물리·화학적 성질이 같은 물질의 큰 덩어리 형태와 뚜렷이 다른 경우가 많다.","그 노과학자는 말년에 해외로 이주했고, 30여 년 전 고향을 떠난 뒤로 다시는 돌아가지 못해 이것이 평생의 한으로 남았다.","과학 기술이 아무리 발전해도 책 읽기가 주는 고요함과 생각할 거리는 어떤 전자 기기로도 대신하기 어렵다."],"ow":[[["秦始皇陵","Qín Shǐhuáng líng","진시황릉"],["兵马俑","bīngmǎyǒng","병마용"],["陶俑","táoyǒng","도용(흙 인형)"],["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"],["面孔","miànkǒng","얼굴"]],[["纳米","nàmǐ","나노"],["比表面积","bǐbiǎomiànjī","비표면적"],["宏观","hóngguān","거시적"],["差异","chāyì","차이"]],[["移居","yíjū","이주하다"],["故乡","gùxiāng","고향"],["遗憾","yíhàn","유감, 한"]],[["宁静","níngjìng","고요하다"],["设备","shèbèi","기기"],["取代","qǔdài","대신하다"]]]},{"o":["早在两千多年前，我国劳动人民就已经掌握了利用天然气煮盐的技术，这在世界上也是相当早的。","鸟类迁徙时能够准确辨别方向，可能与它们能感知地球磁场有关，但其具体机制至今尚无定论。","这位旅居海外多年的画家，始终对中国传统水墨画情有独钟，作品中常常流露出浓浓的乡愁。","研究团队关于这种新型病毒的传播途径和变异规律，开展了为期半年的追踪调查。"],"a":3,"type":"개사구 위치","why":"“关于”로 만든 말은 주어 뒤에 올 수 없고 문장 맨 앞에 와야 한다.","fix":"关于这种新型病毒的传播途径和变异规律，研究团队开展了为期半年的追踪调查。","words":[["天然气","tiānránqì","천연가스"],["迁徙","qiānxǐ","(철새가) 이동하다"],["磁场","cíchǎng","자기장"],["定论","dìnglùn","정설"],["情有独钟","qíng yǒu dú zhōng","유독 좋아하다"],["变异","biànyì","변이"]],"tr":["이미 2천여 년 전에 우리나라 사람들은 천연가스로 소금을 끓여 만드는 기술을 익혔는데, 이는 세계적으로도 꽤 이른 편이다.","새가 철 따라 이동할 때 방향을 정확히 가리는 것은 지구 자기장을 느낄 수 있기 때문일 수 있지만, 구체적인 원리는 아직 정설이 없다.","여러 해 외국에 머문 이 화가는 늘 중국 전통 수묵화를 유독 좋아했고, 작품마다 짙은 향수가 묻어난다.","연구팀은 이 신종 바이러스의 전파 경로와 변이 규칙을 놓고 반년 동안 추적 조사를 벌였다."],"ow":[[["劳动人民","láodòng rénmín","근로 대중"],["掌握","zhǎngwò","익히다"],["天然气","tiānránqì","천연가스"]],[["迁徙","qiānxǐ","(철새가) 이동하다"],["辨别","biànbié","분별하다"],["磁场","cíchǎng","자기장"],["机制","jīzhì","원리, 메커니즘"],["定论","dìnglùn","정설"]],[["旅居","lǚjū","타지에 머물다"],["水墨画","shuǐmòhuà","수묵화"],["情有独钟","qíng yǒu dú zhōng","유독 좋아하다"],["流露","liúlù","드러나다"],["乡愁","xiāngchóu","향수"]],[["病毒","bìngdú","바이러스"],["途径","tújìng","경로"],["变异","biànyì","변이"],["追踪","zhuīzōng","추적하다"]]]},{"o":["这部以中国空间站为背景拍摄的科幻电影，对许多青少年观众都十分感兴趣。","盐碱地由于土壤中含盐量过高，大多数农作物难以正常生长，改良起来往往需要耗费大量时间和资金。","景泰蓝是北京著名的传统手工艺品，因在明朝景泰年间盛行、且多用蓝色釉料而得名。","哪怕只是一句真诚的问候，也可能给身处困境的人带去莫大的温暖和力量。"],"a":0,"type":"개사구 위치","why":"흥미를 느끼는 쪽은 관객인데 “对”가 관객 앞에 붙어 주객이 뒤바뀌었다. “观众对电影感兴趣” 순서여야 한다.","fix":"许多青少年观众都对这部以中国空间站为背景拍摄的科幻电影十分感兴趣。","words":[["空间站","kōngjiānzhàn","우주정거장"],["科幻","kēhuàn","공상과학"],["盐碱地","yánjiǎndì","염알칼리 토양"],["景泰蓝","jǐngtàilán","경태람(칠보 공예)"],["困境","kùnjìng","곤경"],["莫大","mòdà","매우 크다"]],"tr":["중국 우주정거장을 배경으로 찍은 이 공상과학 영화에 많은 청소년 관객이 큰 흥미를 보였다.","염알칼리 땅은 흙에 소금기가 너무 많아 대부분의 작물이 제대로 자라기 어렵고, 땅을 바꾸려면 시간과 돈이 많이 드는 경우가 많다.","경태람은 베이징의 유명한 전통 공예품으로, 명나라 경태 연간에 성행했고 주로 푸른 유약을 써서 이런 이름이 붙었다.","진심 어린 안부 한마디일지라도, 어려움에 처한 사람에게는 더없는 따뜻함과 힘이 될 수 있다."],"ow":[[["空间站","kōngjiānzhàn","우주정거장"],["科幻","kēhuàn","공상과학"]],[["盐碱地","yánjiǎndì","염알칼리 토양"],["农作物","nóngzuòwù","농작물"],["改良","gǎiliáng","개량하다"],["耗费","hàofèi","소모하다"]],[["景泰蓝","jǐngtàilán","경태람(칠보 공예)"],["盛行","shèngxíng","성행하다"],["釉料","yòuliào","유약 재료"],["得名","démíng","이름을 얻다"]],[["哪怕","nǎpà","설령 ~일지라도"],["真诚","zhēnchéng","진실하다"],["困境","kùnjìng","곤경"],["莫大","mòdà","매우 크다"]]]},{"o":["自行车最早出现于十九世纪初的欧洲，当时的车子既没有链条，也没有脚踏板，全靠双脚蹬地前进。","在这次国际会议上，许多我国年轻的人工智能研究者作了精彩的学术报告，受到了同行的好评。","在现代化的物流仓库里，智能物流机器人能够根据系统指令，自动把货架运送到拣货员面前。","尽管人工降雨技术已相当成熟，但它只能在具备一定云层条件的情况下实施，并不能凭空“造”出雨来。"],"a":1,"type":"관형어 순서","why":"소속을 나타내는 “我国”가 수량 “许多”보다 앞에 와야 한다. “我国许多年轻的…”가 맞는 순서다.","fix":"在这次国际会议上，我国许多年轻的人工智能研究者作了精彩的学术报告，受到了同行的好评。","words":[["链条","liàntiáo","체인"],["踏板","tàbǎn","페달"],["人工降雨","réngōng jiàngyǔ","인공 강우"],["凭空","píngkōng","아무 근거 없이"],["指令","zhǐlìng","명령"],["拣货","jiǎnhuò","주문 상품을 골라 담다"]],"tr":["자전거는 19세기 초 유럽에서 처음 나왔는데, 당시에는 체인도 페달도 없어 두 발로 땅을 차며 나아갔다.","이번 국제회의에서 우리나라의 많은 젊은 인공지능 연구자들이 훌륭한 학술 발표를 해 동료 연구자들의 호평을 받았다.","현대식 물류 창고에서는 스마트 물류 로봇이 시스템 명령에 따라 선반을 상품 고르는 직원 앞까지 자동으로 옮겨 준다.","인공 강우 기술은 이미 꽤 무르익었지만 일정한 구름 조건이 갖춰졌을 때만 할 수 있어, 아무것도 없는 데서 비를 ‘만들어’ 내지는 못한다."],"ow":[[["链条","liàntiáo","체인"],["踏板","tàbǎn","페달"],["蹬","dēng","(발로) 차다"]],[["研究者","yánjiūzhě","연구자"],["同行","tóngháng","같은 업계 사람"],["好评","hǎopíng","호평"]],[["物流","wùliú","물류"],["仓库","cāngkù","창고"],["指令","zhǐlìng","명령"],["货架","huòjià","진열대, 선반"],["拣货员","jiǎnhuòyuán","주문 상품을 골라 담는 직원"]],[["人工降雨","réngōng jiàngyǔ","인공 강우"],["成熟","chéngshú","성숙하다"],["云层","yúncéng","구름층"],["凭空","píngkōng","아무 근거 없이"]]]},{"o":["植物的根系通常具有向地性，即使把种子倒着埋进土里，根最终也会转向下方生长。","这部长篇小说以一个普通家庭三代人的命运变迁为线索，展现了中国社会半个世纪以来的巨大变化。","考古队员在这座西汉墓葬中发掘出了精美的一批青铜酒器，器身上还刻有清晰的铭文。","引力波是爱因斯坦在一百年前根据广义相对论作出的预言，直到2015年才被科学家首次直接探测到。"],"a":2,"type":"관형어 순서","why":"수량 “一批”가 모양을 말하는 “精美的”보다 앞에 와야 한다. “一批精美的青铜酒器”가 맞다.","fix":"考古队员在这座西汉墓葬中发掘出了一批精美的青铜酒器，器身上还刻有清晰的铭文。","words":[["根系","gēnxì","뿌리 체계"],["变迁","biànqiān","변천"],["墓葬","mùzàng","무덤"],["铭文","míngwén","(그릇 등에 새긴) 명문"],["引力波","yǐnlìbō","중력파"],["广义相对论","guǎngyì xiāngduìlùn","일반상대성이론"]],"tr":["식물의 뿌리는 대개 땅 쪽으로 자라는 성질이 있어, 씨앗을 거꾸로 심어도 뿌리는 결국 아래쪽으로 방향을 틀어 자란다.","이 장편 소설은 평범한 한 집안 3대의 운명 변화를 줄기로 삼아, 반세기 동안 중국 사회가 겪은 큰 변화를 보여 준다.","고고학 대원들은 이 서한 시대 무덤에서 정교한 청동 술그릇 한 무더기를 발굴했는데, 그릇 몸통에는 또렷한 명문까지 새겨져 있었다.","중력파는 아인슈타인이 백 년 전에 일반상대성이론에 근거해 예언한 것으로, 2015년에야 과학자들이 처음 직접 찾아냈다."],"ow":[[["根系","gēnxì","뿌리 체계"],["向地性","xiàngdìxìng","굴지성"],["种子","zhǒngzi","씨앗"]],[["长篇小说","chángpiān xiǎoshuō","장편 소설"],["变迁","biànqiān","변천"],["线索","xiànsuǒ","줄거리의 실마리"],["展现","zhǎnxiàn","보여 주다"]],[["西汉","Xī Hàn","서한"],["墓葬","mùzàng","무덤"],["发掘","fājué","발굴하다"],["精美","jīngměi","정교하고 아름답다"],["铭文","míngwén","명문"]],[["引力波","yǐnlìbō","중력파"],["爱因斯坦","Àiyīnsītǎn","아인슈타인"],["广义相对论","guǎngyì xiāngduìlùn","일반상대성이론"],["探测","tàncè","탐지하다"]]]},{"o":["地球大气层中的臭氧层能够吸收太阳光中绝大部分的紫外线，因而被称为地球生命的“保护伞”。","汉字从甲骨文、金文发展到小篆、隶书和楷书，字形逐渐由繁到简，书写也越来越便捷。","俗话说“病从口入”，这说明古人很早就已经认识到饮食卫生与身体健康之间的密切关系。","这是一项达到国际领先水平的我国科研团队自主完成的重大成果，标志着我国在可控核聚变领域迈出了关键一步。"],"a":3,"type":"관형어 순서","why":"누가 했는지를 말하는 “我国科研团队自主完成的”와 수량 “一项”이 성질을 말하는 “达到国际领先水平的”보다 앞에 와야 한다.","fix":"这是我国科研团队自主完成的一项达到国际领先水平的重大成果，标志着我国在可控核聚变领域迈出了关键一步。","words":[["臭氧层","chòuyǎngcéng","오존층"],["紫外线","zǐwàixiàn","자외선"],["隶书","lìshū","예서"],["楷书","kǎishū","해서"],["俗话","súhuà","속담"],["可控核聚变","kěkòng héjùbiàn","제어 핵융합"]],"tr":["지구 대기의 오존층은 햇빛 속 자외선을 대부분 흡수해 지구 생명의 ‘보호 우산’이라 불린다.","한자는 갑골문과 금문에서 소전, 예서, 해서로 발전하며 글자 모양이 점차 복잡함에서 간단함으로 바뀌었고 쓰기도 갈수록 편해졌다.","‘병은 입으로 들어온다’는 속담은 옛사람들이 일찍부터 음식 위생과 몸 건강의 밀접한 관계를 알고 있었다는 것을 보여 준다.","이것은 우리나라 연구팀이 독자적으로 이룬, 국제 최고 수준에 이른 중대한 성과로서, 제어 핵융합 분야에서 결정적인 한 걸음을 내디뎠음을 뜻한다."],"ow":[[["大气层","dàqìcéng","대기층"],["臭氧层","chòuyǎngcéng","오존층"],["紫外线","zǐwàixiàn","자외선"]],[["甲骨文","jiǎgǔwén","갑골문"],["小篆","xiǎozhuàn","소전"],["隶书","lìshū","예서"],["楷书","kǎishū","해서"],["便捷","biànjié","편리하다"]],[["俗话","súhuà","속담"],["病从口入","bìng cóng kǒu rù","병은 입으로 들어온다"],["卫生","wèishēng","위생"]],[["领先","lǐngxiān","앞서다"],["自主","zìzhǔ","독자적으로"],["标志","biāozhì","상징하다"],["可控核聚变","kěkòng héjùbiàn","제어 핵융합"]]]},{"o":["经过反复论证，专家们最终通过并修改了这份关于火星采样返回任务的可行性报告。","古代丝绸之路不仅是一条商贸之路，更是东西方文明交流互鉴的桥梁，佛教、造纸术等都曾借助它传播。","实验表明，把一枚鸡蛋放入浓盐水中，它会逐渐浮起来，这是因为盐水的密度比清水大。","当地政府鉴于近年来山体滑坡频发、威胁群众安全，决定对沿河谷居住的二百多户居民实施整体搬迁。"],"a":0,"type":"동작 순서","why":"보고서는 먼저 고치고 나서 통과시키는 것이 순서인데 “通过并修改”로 거꾸로 썼다.","fix":"经过反复论证，专家们最终修改并通过了这份关于火星采样返回任务的可行性报告。","words":[["论证","lùnzhèng","논증하다"],["采样","cǎiyàng","시료를 채취하다"],["可行性","kěxíngxìng","실현 가능성"],["互鉴","hùjiàn","서로 본받다"],["鉴于","jiànyú","~을 감안하여"],["滑坡","huápō","산사태"]],"tr":["거듭된 검토 끝에 전문가들은 화성 시료 회수 임무에 관한 이 타당성 보고서를 마침내 수정하고 통과시켰다.","옛 실크로드는 교역의 길일 뿐 아니라 동서 문명이 서로 배우는 다리였고, 불교와 제지술 등이 모두 이 길을 통해 전해졌다.","실험에 따르면 달걀을 진한 소금물에 넣으면 서서히 떠오르는데, 이는 소금물의 밀도가 맹물보다 크기 때문이다.","현지 정부는 최근 산사태가 잦아 주민 안전을 위협하는 점을 감안해, 강 골짜기를 따라 사는 2백여 가구를 통째로 이주시키기로 했다."],"ow":[[["论证","lùnzhèng","논증하다"],["采样","cǎiyàng","시료를 채취하다"],["可行性","kěxíngxìng","실현 가능성"]],[["丝绸之路","Sīchóu zhī Lù","실크로드"],["商贸","shāngmào","상업과 무역"],["互鉴","hùjiàn","서로 본받다"],["借助","jièzhù","힘을 빌리다"]],[["盐水","yánshuǐ","소금물"],["密度","mìdù","밀도"]],[["鉴于","jiànyú","~을 감안하여"],["滑坡","huápō","산사태"],["频发","pínfā","자주 발생하다"],["河谷","hégǔ","강 골짜기"],["搬迁","bānqiān","이전하다"]]]},{"o":["青铜是铜与锡或铅的合金，与纯铜相比，它熔点更低、硬度更高，因而更适合铸造器物。","农历设置闰月是为了协调月相周期与回归年之间的差异，使农历月份与季节大致保持对应。","这次为期两周的人工智能夏令营，让参加活动的中学生们掌握并了解了机器学习的基本原理。","这位纪录片导演历时三年，追踪拍摄了一群斑头雁从青海湖飞越喜马拉雅山的迁徙全过程。"],"a":2,"type":"동작 순서","why":"먼저 알고(了解) 그다음 익히는(掌握) 것이 순서인데 “掌握并了解”로 거꾸로 썼다.","fix":"这次为期两周的人工智能夏令营，让参加活动的中学生们了解并掌握了机器学习的基本原理。","words":[["合金","héjīn","합금"],["熔点","róngdiǎn","녹는점"],["闰月","rùnyuè","윤달"],["回归年","huíguīnián","태양년"],["夏令营","xiàlìngyíng","여름 캠프"],["斑头雁","bāntóuyàn","줄기러기"]],"tr":["청동은 구리에 주석이나 납을 섞은 합금으로, 순수한 구리보다 녹는점이 낮고 단단해서 그릇을 주조하기에 더 알맞다.","음력에 윤달을 두는 것은 달의 위상 주기와 태양년 사이의 차이를 맞춰, 음력 달이 계절과 대체로 맞아떨어지게 하려는 것이다.","2주 동안 열린 이번 인공지능 여름 캠프에서 참가한 중학생들은 기계 학습의 기본 원리를 이해하고 익혔다.","이 다큐멘터리 감독은 3년에 걸쳐 줄기러기 무리가 칭하이호에서 히말라야산맥을 넘어 이동하는 전 과정을 따라가며 찍었다."],"ow":[[["青铜","qīngtóng","청동"],["合金","héjīn","합금"],["熔点","róngdiǎn","녹는점"],["硬度","yìngdù","경도"],["铸造","zhùzào","주조하다"]],[["农历","nónglì","음력"],["闰月","rùnyuè","윤달"],["协调","xiétiáo","조정하다"],["月相","yuèxiàng","달의 위상"],["回归年","huíguīnián","태양년"]],[["为期","wéiqī","~을 기한으로"],["夏令营","xiàlìngyíng","여름 캠프"],["机器学习","jīqì xuéxí","기계 학습"],["原理","yuánlǐ","원리"]],[["纪录片","jìlùpiàn","다큐멘터리"],["追踪","zhuīzōng","추적하다"],["斑头雁","bāntóuyàn","줄기러기"],["青海湖","Qīnghǎi Hú","칭하이호"],["迁徙","qiānxǐ","(철새가) 이동하다"]]]}],[{"o":["甲骨文是商代刻在龟甲和兽骨上的文字，它的发现把有文字可考的中国历史提前到了三千多年前。","只有在超低温和高真空的条件下，这种量子芯片就能保持稳定的运行状态。","即使是经验最丰富的潜水员，在缺乏专业装备的情况下也不敢贸然进入这片暗流涌动的海域。","有些人认为喝咖啡会导致骨质疏松，但现有研究表明，适量饮用对大多数健康成年人并无明显危害。"],"a":1,"type":"짝 오류","why":"“只有”는 “才”와 짝을 이루는데 “就”를 썼다.","fix":"只有在超低温和高真空的条件下，这种量子芯片才能保持稳定的运行状态。","words":[["甲骨文","jiǎgǔwén","갑골문"],["龟甲","guījiǎ","거북 등딱지"],["真空","zhēnkōng","진공"],["贸然","màorán","경솔하게"],["暗流涌动","àn liú yǒng dòng","물밑 흐름이 거세다"],["骨质疏松","gǔzhì shūsōng","골다공증"]],"tr":["갑골문은 상나라 때 거북 등딱지와 짐승 뼈에 새긴 문자로, 그 발견으로 문자로 확인할 수 있는 중국 역사가 3천여 년 전까지 거슬러 올라갔다.","초저온과 고진공 조건에서만 이 양자 칩은 안정적으로 작동할 수 있다.","아무리 경험 많은 잠수부라도 전문 장비가 없으면 물밑 흐름이 거센 이 바다에 함부로 들어가지 못한다.","커피가 골다공증을 일으킨다고 여기는 사람도 있지만, 지금까지의 연구로는 적당히 마시면 대부분의 건강한 성인에게 뚜렷한 해가 없다."],"ow":[[["甲骨文","jiǎgǔwén","갑골문"],["龟甲","guījiǎ","거북 등딱지"],["兽骨","shòugǔ","짐승 뼈"],["可考","kěkǎo","고증할 수 있다"]],[["超低温","chāodīwēn","초저온"],["真空","zhēnkōng","진공"],["量子","liàngzǐ","양자"],["芯片","xīnpiàn","칩"]],[["潜水员","qiánshuǐyuán","잠수부"],["装备","zhuāngbèi","장비"],["贸然","màorán","경솔하게"],["暗流涌动","àn liú yǒng dòng","물밑 흐름이 거세다"],["海域","hǎiyù","해역"]],[["骨质疏松","gǔzhì shūsōng","골다공증"],["适量","shìliàng","적당량"],["危害","wēihài","해, 위해"]]]},{"o":["冬虫夏草是一种真菌寄生在蝙蝠蛾幼虫体内形成的复合体，并非像名字所说的那样“冬天是虫，夏天是草”。","这条全自动饮料灌装生产线每小时可灌装三万余瓶，从洗瓶到贴标全程无需人工干预。","北极熊的毛并不是白色的，而是中空透明的，只是由于光线的散射才看起来呈白色。","既然这项技术在实验室中已经得到了反复验证，那么才可以考虑在临床上进行小范围试用。"],"a":3,"type":"짝 오류","why":"“既然”은 “就”와 짝을 이루는데 “才”를 썼다.","fix":"既然这项技术在实验室中已经得到了反复验证，那么就可以考虑在临床上进行小范围试用。","words":[["冬虫夏草","dōng chóng xià cǎo","동충하초"],["真菌","zhēnjūn","진균"],["寄生","jìshēng","기생하다"],["散射","sǎnshè","산란"],["临床","línchuáng","임상"],["灌装","guànzhuāng","(병에) 담다"],["干预","gānyù","개입하다"]],"tr":["동충하초는 진균이 박쥐나방 애벌레 몸속에 기생해 생긴 복합체로, 이름처럼 ‘겨울엔 벌레, 여름엔 풀’인 것이 아니다.","이 완전 자동 음료 충전 라인은 한 시간에 3만여 병을 채울 수 있고, 병 씻기부터 라벨 붙이기까지 전 과정에 사람이 손댈 필요가 없다.","북극곰의 털은 하얀색이 아니라 속이 비고 투명한데, 빛이 흩어지기 때문에 하얗게 보일 뿐이다.","이 기술이 이미 실험실에서 거듭 검증되었으니, 임상에서 작은 범위로 시험 사용하는 것을 생각해 볼 수 있다."],"ow":[[["冬虫夏草","dōng chóng xià cǎo","동충하초"],["真菌","zhēnjūn","진균"],["寄生","jìshēng","기생하다"],["幼虫","yòuchóng","애벌레"],["复合体","fùhétǐ","복합체"]],[["灌装","guànzhuāng","(병에) 담다"],["生产线","shēngchǎnxiàn","생산 라인"],["贴标","tiēbiāo","라벨을 붙이다"],["干预","gānyù","개입하다"]],[["北极熊","běijíxióng","북극곰"],["中空","zhōngkōng","속이 비다"],["透明","tòumíng","투명하다"],["散射","sǎnshè","산란"]],[["既然","jìrán","~한 이상"],["验证","yànzhèng","검증하다"],["临床","línchuáng","임상"]]]},{"o":["与其把有限的经费分散投入到几十个小项目中，宁可集中力量攻克一两个核心技术难题。","人体内的生物钟受光照影响很大，所以长时间在夜间使用电子屏幕，容易扰乱正常的睡眠节律。","黄梅戏起源于湖北黄梅一带，后在安徽安庆发展壮大，代表剧目《天仙配》至今仍广为传唱。","尽管父母一再劝说，他还是毅然放弃了城市里的稳定工作，回到草原上当起了牧民。"],"a":0,"type":"짝 오류","why":"“与其”은 “不如”와 짝을 이루는데 “宁可”를 썼다.","fix":"与其把有限的经费分散投入到几十个小项目中，不如集中力量攻克一两个核心技术难题。","words":[["攻克","gōngkè","(난관을) 극복하다"],["生物钟","shēngwùzhōng","생체 시계"],["节律","jiélǜ","리듬"],["剧目","jùmù","공연 작품"],["毅然","yìrán","단호히"],["牧民","mùmín","목축민"]],"tr":["한정된 경비를 수십 개의 작은 과제에 나누어 쓰기보다는, 힘을 모아 한두 가지 핵심 기술 난제를 해결하는 편이 낫다.","몸속 생체 시계는 빛의 영향을 크게 받아서, 밤에 전자 화면을 오래 쓰면 정상적인 수면 리듬이 흐트러지기 쉽다.","황매희는 후베이성 황메이 일대에서 생겨나 안후이성 안칭에서 크게 성장했고, 대표작 「천선배」는 지금도 널리 불린다.","부모가 거듭 말렸지만 그는 끝내 도시의 안정된 직장을 단호히 버리고 초원으로 돌아가 목축민이 되었다."],"ow":[[["与其","yǔqí","~하기보다는"],["经费","jīngfèi","경비"],["攻克","gōngkè","(난관을) 극복하다"],["核心","héxīn","핵심"]],[["生物钟","shēngwùzhōng","생체 시계"],["屏幕","píngmù","화면"],["扰乱","rǎoluàn","어지럽히다"],["节律","jiélǜ","리듬"]],[["黄梅戏","huángméixì","황매희(지방극)"],["起源","qǐyuán","기원하다"],["剧目","jùmù","공연 작품"],["天仙配","Tiānxiān Pèi","천선배"],["传唱","chuánchàng","전해 부르다"]],[["劝说","quànshuō","설득하다"],["毅然","yìrán","단호히"],["草原","cǎoyuán","초원"],["牧民","mùmín","목축민"]]]},{"o":["电池的发明者伏打是意大利物理学家，电压的单位“伏特”正是以他的名字命名的。","铁路货运部门推出了“门到门”的运输服务，货主不必亲自前往车站就能办理托运手续。","不但这款机器人能够识别人的面部表情，而且还能根据对方的情绪调整说话的语气。","父母过度保护孩子，看似是出于爱，实际上却可能剥夺他们独立面对挫折、积累经验的机会。"],"a":2,"type":"관련사 위치","why":"앞뒤 주어가 같으면(这款机器人) “不但”은 주어 뒤에 와야 한다.","fix":"这款机器人不但能够识别人的面部表情，而且还能根据对方的情绪调整说话的语气。","words":[["伏打","Fúdǎ","볼타"],["命名","mìngmíng","이름을 붙이다"],["剥夺","bōduó","빼앗다"],["货运","huòyùn","화물 운송"],["托运","tuōyùn","탁송하다"]],"tr":["전지를 발명한 볼타는 이탈리아의 물리학자로, 전압 단위 ‘볼트’는 바로 그의 이름에서 따왔다.","철도 화물 부서가 ‘문에서 문까지’ 운송 서비스를 내놓아, 화주는 직접 역에 가지 않아도 탁송 절차를 마칠 수 있다.","이 로봇은 사람의 얼굴 표정을 알아볼 수 있을 뿐 아니라, 상대의 감정에 따라 말투도 바꿀 수 있다.","부모가 아이를 지나치게 보호하는 것은 사랑에서 나온 것처럼 보이지만, 사실은 아이가 혼자 좌절을 마주하고 경험을 쌓을 기회를 빼앗을 수 있다."],"ow":[[["伏打","Fúdǎ","볼타"],["电压","diànyā","전압"],["伏特","fútè","볼트"],["命名","mìngmíng","이름을 붙이다"]],[["货运","huòyùn","화물 운송"],["货主","huòzhǔ","화주"],["办理","bànlǐ","처리하다"],["托运","tuōyùn","탁송하다"]],[["识别","shíbié","식별하다"],["面部","miànbù","얼굴"],["语气","yǔqì","말투"]],[["过度","guòdù","지나치다"],["剥夺","bōduó","빼앗다"],["挫折","cuòzhé","좌절"],["积累","jīlěi","쌓다"]]]},{"o":["由于没有大气层的保护，月球表面昼夜温差极大，白天可达一百多摄氏度，夜间则会降到零下一百多摄氏度。","这首民歌旋律优美、节奏明快，经过一代代人的传唱，早已成为当地人心中的“乡音”。","心理学家发现，人们往往会高估自己的判断力，这种过度自信在投资决策中尤为常见。","这家公司不仅率先将固态电池应用于量产车型，而且国内其他车企也纷纷跟进，加快了相关技术的研发步伐。"],"a":3,"type":"관련사 위치","why":"앞뒤 주어가 다르면(这家公司 / 其他车企) “不仅”은 첫 주어 앞에 와야 한다.","fix":"不仅这家公司率先将固态电池应用于量产车型，而且国内其他车企也纷纷跟进，加快了相关技术的研发步伐。","words":[["昼夜温差","zhòuyè wēnchā","일교차"],["旋律","xuánlǜ","선율"],["高估","gāogū","과대평가하다"],["固态电池","gùtài diànchí","전고체 배터리"],["量产","liàngchǎn","대량 생산"],["跟进","gēnjìn","뒤따르다"]],"tr":["대기층의 보호가 없어 달 표면은 일교차가 매우 커서, 낮에는 섭씨 100도 넘게 오르고 밤에는 영하 100도 아래로 떨어진다.","이 민요는 가락이 아름답고 박자가 경쾌해, 대대로 불리면서 오래전에 현지 사람들 마음속 ‘고향의 소리’가 되었다.","심리학자들은 사람들이 흔히 자기 판단력을 과대평가하며, 이런 지나친 자신감이 투자 결정에서 특히 흔하다는 것을 발견했다.","이 회사가 앞장서서 전고체 배터리를 양산 차종에 쓴 데다, 국내 다른 완성차 업체들도 잇따라 뒤따르며 관련 기술 개발에 속도를 냈다."],"ow":[[["大气层","dàqìcéng","대기층"],["昼夜温差","zhòuyè wēnchā","일교차"],["摄氏度","shèshìdù","섭씨 온도"]],[["民歌","míngē","민요"],["旋律","xuánlǜ","선율"],["明快","míngkuài","경쾌하다"],["乡音","xiāngyīn","고향 말씨, 고향의 소리"]],[["高估","gāogū","과대평가하다"],["判断力","pànduànlì","판단력"],["尤为","yóuwéi","특히"],["决策","juécè","결정"]],[["率先","shuàixiān","앞장서다"],["固态电池","gùtài diànchí","전고체 배터리"],["量产","liàngchǎn","대량 생산"],["跟进","gēnjìn","뒤따르다"]]]},{"o":["这种碳纤维复合材料的密度只有钢的四分之一左右，因此其强度却能达到钢的数倍，在航空航天领域应用广泛。","端砚、歙砚、洮砚和澄泥砚被誉为中国“四大名砚”，其中端砚因石质细腻、发墨快而居首位。","这名运动员在比赛中意外受伤，但他忍着剧痛坚持跑完了全程，赢得了全场观众经久不息的掌声。","如今，许多城市开始利用大数据分析交通流量，对红绿灯的时长进行动态调整，以缓解早晚高峰的拥堵。"],"a":0,"type":"논리 관계","why":"가볍다는 것과 강하다는 것은 원인과 결과가 아니라 대조인데 “因此…却”로 이어 앞뒤 관계가 엉켰다.","fix":"这种碳纤维复合材料的密度只有钢的四分之一左右，但其强度却能达到钢的数倍，在航空航天领域应用广泛。","words":[["碳纤维","tànxiānwéi","탄소섬유"],["复合材料","fùhé cáiliào","복합 재료"],["航空航天","hángkōng hángtiān","항공우주"],["发墨","fāmò","(벼루에) 먹이 잘 갈리다"],["经久不息","jīng jiǔ bù xī","오래도록 그치지 않다"],["拥堵","yōngdǔ","교통 체증"]],"tr":["이 탄소섬유 복합 소재는 밀도가 강철의 약 4분의 1밖에 안 되지만 강도는 강철의 몇 배에 이르러, 항공우주 분야에서 널리 쓰인다.","단연, 흡연, 조연, 징니연은 중국 ‘4대 명연’으로 불리며, 그중 단연은 돌결이 곱고 먹이 잘 갈려 으뜸으로 꼽힌다.","이 선수는 경기 중 뜻밖에 다쳤지만 극심한 통증을 참고 끝까지 달려, 경기장을 가득 메운 관중의 끊이지 않는 박수를 받았다.","요즘 많은 도시는 빅데이터로 교통량을 분석해 신호등 시간을 실시간으로 조정하며, 출퇴근 시간의 정체를 덜고 있다."],"ow":[[["碳纤维","tànxiānwéi","탄소섬유"],["复合材料","fùhé cáiliào","복합 재료"],["密度","mìdù","밀도"],["航空航天","hángkōng hángtiān","항공우주"]],[["端砚","duānyàn","단연(벼루)"],["名砚","míngyàn","명품 벼루"],["细腻","xìnì","곱다"],["发墨","fāmò","먹이 잘 갈리다"]],[["剧痛","jùtòng","극심한 통증"],["全程","quánchéng","전 구간"],["经久不息","jīng jiǔ bù xī","오래도록 그치지 않다"]],[["大数据","dàshùjù","빅데이터"],["流量","liúliàng","유량, 교통량"],["动态","dòngtài","동적"],["拥堵","yōngdǔ","교통 체증"]]]},{"o":["风筝起源于中国，相传最早由墨子用木头制成，后来人们改用纸张和竹篾，才逐渐演变为今天的样子。","这道几何难题不但让参加竞赛的数学教授们束手无策，就连普通中学生也感到无从下手。","热气球之所以能升空，是因为球囊内的空气被加热后密度变小，使得整个气球所受的浮力大于其总重力。","一个人的气质与修养，往往体现在待人接物的细节之中，而非华丽的服饰与高谈阔论。"],"a":1,"type":"논리 관계","why":"점층(不但…连…)은 쉬운 쪽에서 어려운 쪽으로 가야 하는데, 교수도 못 푸는 문제를 중학생도 못 푼다고 해 순서가 거꾸로다.","fix":"这道几何难题不但让普通中学生感到无从下手，就连参加竞赛的数学教授们也束手无策。","words":[["墨子","Mòzǐ","묵자"],["竹篾","zhúmiè","대오리"],["束手无策","shù shǒu wú cè","속수무책"],["无从下手","wú cóng xià shǒu","손댈 방법이 없다"],["浮力","fúlì","부력"],["待人接物","dài rén jiē wù","사람을 대하는 태도"]],"tr":["연은 중국에서 비롯되었고, 전설에 따르면 묵자가 처음 나무로 만들었으며 뒤에 종이와 대오리를 쓰면서 점차 오늘날의 모습이 되었다.","이 기하 난제는 대회에 나온 수학 교수들마저 속수무책이게 했고, 평범한 중학생들도 손댈 엄두를 내지 못했다.","열기구가 하늘로 떠오르는 것은 기구 안 공기가 데워져 밀도가 작아지면서, 기구 전체가 받는 부력이 전체 무게보다 커지기 때문이다.","한 사람의 기품과 교양은 화려한 옷차림이나 거창한 말이 아니라, 사람을 대하고 일을 처리하는 작은 부분에서 드러나는 경우가 많다."],"ow":[[["风筝","fēngzheng","연"],["墨子","Mòzǐ","묵자"],["竹篾","zhúmiè","대오리"],["演变","yǎnbiàn","변천하다"]],[["几何","jǐhé","기하"],["束手无策","shù shǒu wú cè","속수무책"],["无从下手","wú cóng xià shǒu","손댈 방법이 없다"]],[["热气球","rèqìqiú","열기구"],["球囊","qiúnáng","기구 주머니"],["密度","mìdù","밀도"],["浮力","fúlì","부력"]],[["修养","xiūyǎng","교양"],["待人接物","dài rén jiē wù","사람을 대하는 태도"],["华丽","huálì","화려하다"],["高谈阔论","gāo tán kuò lùn","거창하게 떠벌리다"]]]},{"o":["物流公司借助大数据分析不断优化运输路线，有效减少了货车空驶的次数，降低了运输成本。","研究者发现，经常阅读文学作品的人，在理解他人情绪和想法方面往往表现得更加出色。","虽然这款智能手表的续航时间长达两周，但是用户不必频繁充电，在户外旅行时使用十分方便。","古人在没有冰箱的情况下，常利用冬季储存的天然冰块来保存食物，这种藏冰的地方被称为“冰窖”。"],"a":2,"type":"논리 관계","why":"배터리가 오래가서 자주 충전할 필요가 없는 것은 원인과 결과인데 “虽然…但是”(역접)로 이었다.","fix":"由于这款智能手表的续航时间长达两周，因此用户不必频繁充电，在户外旅行时使用十分方便。","words":[["频繁","pínfán","잦다"],["储存","chǔcún","저장하다"],["冰窖","bīngjiào","얼음 창고"],["优化","yōuhuà","최적화하다"],["空驶","kōngshǐ","빈 차로 달리다"]],"tr":["물류 회사는 빅데이터 분석으로 운송 경로를 계속 최적화해, 화물차가 빈 차로 다니는 횟수를 줄이고 운송비를 낮췄다.","연구자들은 문학 작품을 자주 읽는 사람이 다른 사람의 감정과 생각을 이해하는 데 더 뛰어난 경우가 많다는 것을 발견했다.","이 스마트워치는 배터리가 2주나 가서 사용자가 자주 충전할 필요가 없으므로, 야외 여행 때 쓰기에 아주 편리하다.","냉장고가 없던 시절 옛사람들은 겨울에 저장해 둔 천연 얼음으로 음식을 보관하곤 했는데, 이렇게 얼음을 보관하는 곳을 ‘빙고’라 불렀다."],"ow":[[["物流","wùliú","물류"],["优化","yōuhuà","최적화하다"],["货车","huòchē","화물차"],["空驶","kōngshǐ","빈 차로 달리다"]],[["文学","wénxué","문학"],["出色","chūsè","뛰어나다"]],[["续航","xùháng","(배터리) 지속 시간"],["频繁","pínfán","잦다"],["户外","hùwài","야외"]],[["储存","chǔcún","저장하다"],["冰块","bīngkuài","얼음덩이"],["冰窖","bīngjiào","얼음 창고"]]]},{"o":["这家轮胎厂在生产线上安装了上百个监测装置，一旦某道工序的数据出现异常，系统就会自动报警。","这家剧院在保留老建筑原有风貌的基础上，增设了现代化的灯光和音响设备。","近年来，随着高速铁路网络不断延伸，许多偏远地区的出行条件得到了极大改善，旅游业也随之兴旺起来。","对于人工智能生成内容的版权归属问题上，目前法学界仍存在较大的争议。"],"a":3,"type":"개사 오용","why":"“…问题上”은 “在”와 짝을 이루어야 하는데 “对于”를 써서 두 구조가 섞였다.","fix":"在人工智能生成内容的版权归属问题上，目前法学界仍存在较大的争议。","words":[["风貌","fēngmào","풍모, 모습"],["兴旺","xīngwàng","번창하다"],["版权","bǎnquán","저작권"],["归属","guīshǔ","귀속"],["工序","gōngxù","공정"],["监测","jiāncè","모니터링하다"]],"tr":["이 타이어 공장은 생산 라인에 감시 장치 백여 개를 달아, 어느 공정의 데이터든 이상이 생기면 시스템이 자동으로 경보를 울린다.","이 극장은 옛 건물의 원래 모습을 그대로 살리면서 현대식 조명과 음향 설비를 새로 들였다.","최근 고속철도망이 계속 뻗어 나가면서 많은 외딴 지역의 교통 여건이 크게 나아졌고, 관광업도 덩달아 번창했다.","인공지능이 만든 콘텐츠의 저작권이 누구에게 있느냐는 문제를 두고 법학계에서는 아직 논란이 크다."],"ow":[[["轮胎","lúntāi","타이어"],["监测","jiāncè","모니터링하다"],["装置","zhuāngzhì","장치"],["工序","gōngxù","공정"],["异常","yìcháng","이상"]],[["剧院","jùyuàn","극장"],["风貌","fēngmào","풍모, 모습"],["增设","zēngshè","증설하다"],["音响","yīnxiǎng","음향"]],[["延伸","yánshēn","뻗어 나가다"],["偏远","piānyuǎn","외지다"],["兴旺","xīngwàng","번창하다"]],[["版权","bǎnquán","저작권"],["归属","guīshǔ","귀속"],["法学界","fǎxuéjiè","법학계"],["争议","zhēngyì","논란"]]]},{"o":["指纹在胎儿期就已形成，此后终身不变，而且即便是同卵双胞胎，指纹也不完全相同。","这位物理学家关于自己的学生要求极为严格，哪怕实验报告中只有一个数据有误，也必须重新测量。","质检员每天要抽检上百件产品，对每一件的尺寸、外观和性能逐项检查并详细记录。","每当夕阳西下，渔船满载而归，整个港口便沉浸在一片忙碌而欢快的气氛之中。"],"a":1,"type":"개사 오용","why":"사람에 대한 태도를 말할 때는 “对”를 써야 하는데 범위·내용을 말하는 “关于”를 썼다.","fix":"这位物理学家对自己的学生要求极为严格，哪怕实验报告中只有一个数据有误，也必须重新测量。","words":[["指纹","zhǐwén","지문"],["胎儿","tāi'ér","태아"],["同卵双胞胎","tóngluǎn shuāngbāotāi","일란성 쌍둥이"],["满载而归","mǎn zài ér guī","가득 싣고 돌아오다"],["质检员","zhìjiǎnyuán","품질 검사원"],["抽检","chōujiǎn","표본 검사하다"]],"tr":["지문은 태아 때 이미 생겨 평생 바뀌지 않으며, 일란성 쌍둥이라도 지문이 완전히 같지는 않다.","이 물리학자는 자기 학생들에게 무척 엄격해서, 실험 보고서에 틀린 수치가 하나만 있어도 반드시 다시 측정하게 한다.","품질 검사원은 날마다 제품 백여 개를 표본 검사하며, 하나하나의 치수와 외관, 성능을 항목별로 살피고 자세히 기록한다.","해가 서쪽으로 질 때마다 고깃배들이 가득 싣고 돌아오고, 항구 전체가 바쁘고 즐거운 분위기에 잠긴다."],"ow":[[["指纹","zhǐwén","지문"],["胎儿","tāi'ér","태아"],["终身","zhōngshēn","평생"],["同卵双胞胎","tóngluǎn shuāngbāotāi","일란성 쌍둥이"]],[["物理学家","wùlǐxuéjiā","물리학자"],["哪怕","nǎpà","설령 ~일지라도"],["测量","cèliáng","측정하다"]],[["质检员","zhìjiǎnyuán","품질 검사원"],["抽检","chōujiǎn","표본 검사하다"],["尺寸","chǐcun","치수"],["逐项","zhúxiàng","항목별로"]],[["夕阳西下","xī yáng xī xià","해가 서쪽으로 지다"],["满载而归","mǎn zài ér guī","가득 싣고 돌아오다"],["沉浸","chénjìn","잠기다"]]]}],[{"o":["中国是茶的故乡，世界上许多国家的种茶技术和饮茶习俗，最初都是直接或间接从中国传入的。","哈雷彗星大约每七十六年回归一次，人类对它的观测记录最早可以追溯到两千多年前的中国。","为了避免实验过程中不出现交叉污染，研究人员每次操作前都会对器材进行严格消毒。","这家餐厅的菜单上没有标价，顾客用餐后根据自己的满意程度随意付费，这种经营方式引起了不少争议。"],"a":2,"type":"이중 부정","why":"“避免”(피하다)에 “不出现”을 붙이면 ‘오염이 안 생기는 것을 피한다’가 되어 뜻이 반대가 된다.","fix":"为了避免实验过程中出现交叉污染，研究人员每次操作前都会对器材进行严格消毒。","words":[["彗星","huìxīng","혜성"],["追溯","zhuīsù","거슬러 올라가다"],["交叉污染","jiāochā wūrǎn","교차 오염"],["消毒","xiāodú","소독하다"],["标价","biāojià","가격을 표시하다"],["争议","zhēngyì","논란"]],"tr":["중국은 차의 고향으로, 세계 여러 나라의 차 재배 기술과 차 마시는 풍습은 처음에 모두 직간접적으로 중국에서 전해졌다.","핼리 혜성은 약 76년마다 한 번씩 돌아오며, 인류의 관측 기록은 가장 이르게는 2천여 년 전 중국까지 거슬러 올라간다.","실험 중 교차 오염을 피하려고 연구진은 매번 작업 전에 기구를 철저히 소독한다.","이 식당의 메뉴판에는 가격이 없고 손님이 식사 뒤 만족한 만큼 알아서 돈을 내는데, 이런 영업 방식은 적잖은 논란을 불렀다."],"ow":[[["故乡","gùxiāng","고향"],["习俗","xísú","풍습"],["间接","jiànjiē","간접적으로"]],[["哈雷彗星","Hāléi Huìxīng","핼리 혜성"],["回归","huíguī","돌아오다"],["观测","guāncè","관측"],["追溯","zhuīsù","거슬러 올라가다"]],[["避免","bìmiǎn","피하다"],["交叉污染","jiāochā wūrǎn","교차 오염"],["器材","qìcái","기구"],["消毒","xiāodú","소독하다"]],[["标价","biāojià","가격을 표시하다"],["随意","suíyì","마음대로"],["争议","zhēngyì","논란"]]]},{"o":["车间的安全规程明确要求，操作冲压设备时切忌不要把手伸进模具区域，以免发生严重的工伤事故。","声音的传播需要介质，因此在没有空气的太空中，即使近在咫尺，宇航员之间也无法直接对话。","江南水乡的民居多为白墙黑瓦，临水而建，与小桥流水共同构成了一幅幅淡雅的水墨画。","他不得不承认，正是那次失败的创业经历，让他学会了如何更加冷静地面对风险。"],"a":0,"type":"이중 부정","why":"“切忌”가 이미 ‘절대 ~하지 마라’인데 “不要”를 붙이면 ‘손을 넣지 않는 것을 피하라’가 되어 뜻이 뒤집힌다.","fix":"车间的安全规程明确要求，操作冲压设备时切忌把手伸进模具区域，以免发生严重的工伤事故。","words":[["宇航员","yǔhángyuán","우주비행사"],["民居","mínjū","민가"],["淡雅","dànyǎ","담백하고 우아하다"],["不得不","bùdébù","어쩔 수 없이"],["规程","guīchéng","규정"],["冲压","chōngyā","프레스 가공"],["模具","mújù","금형"],["工伤","gōngshāng","산업 재해"]],"tr":["작업장 안전 규정은 프레스 설비를 다룰 때 절대 손을 금형 쪽에 넣지 말라고 분명히 요구하는데, 심각한 산업 재해를 막기 위해서다.","소리가 전해지려면 매질이 필요해서, 공기가 없는 우주에서는 바로 곁에 있어도 우주비행사끼리 직접 대화할 수 없다.","강남 물의 고장 민가는 대개 흰 벽에 검은 기와로 물가에 지어져, 작은 다리와 흐르는 물과 함께 담백하고 우아한 수묵화 같은 풍경을 이룬다.","그는 바로 그 실패한 창업 경험이 자신에게 위험을 더 차분하게 마주하는 법을 가르쳐 주었다는 것을 인정하지 않을 수 없었다."],"ow":[[["车间","chējiān","작업장"],["规程","guīchéng","규정"],["冲压","chōngyā","프레스 가공"],["切忌","qièjì","절대 삼가다"],["模具","mújù","금형"],["工伤","gōngshāng","산업 재해"]],[["介质","jièzhì","매질"],["近在咫尺","jìn zài zhǐ chǐ","아주 가까이 있다"],["宇航员","yǔhángyuán","우주비행사"]],[["江南","Jiāngnán","강남(창장강 남쪽)"],["民居","mínjū","민가"],["淡雅","dànyǎ","담백하고 우아하다"],["水墨画","shuǐmòhuà","수묵화"]],[["不得不","bùdébù","어쩔 수 없이"],["创业","chuàngyè","창업"],["风险","fēngxiǎn","위험"]]]},{"o":["人的大脑重量约占体重的百分之二，消耗的能量却占全身总消耗量的百分之二十左右。","我国古代的科举制度从隋朝开始实行，到清朝末年才被废除，前后延续了一千三百多年。","一个人即使才华横溢，如果缺乏与人合作的意识，也很难在团队中真正发挥自己的作用。","为保护珍稀物种，景区管理处明确规定，严禁游客在自然保护区核心区域内不得随意投喂野生动物。"],"a":3,"type":"이중 부정","why":"“严禁”(엄금하다)과 “不得”(해서는 안 된다)가 겹쳐 ‘먹이를 주지 않는 것을 금지한다’는 반대 뜻이 된다.","fix":"为保护珍稀物种，景区管理处明确规定，严禁游客在自然保护区核心区域内随意投喂野生动物。","words":[["科举","kējǔ","과거 제도"],["废除","fèichú","폐지하다"],["才华横溢","cái huá héng yì","재능이 넘치다"],["珍稀","zhēnxī","진귀하고 드물다"],["严禁","yánjìn","엄금하다"],["投喂","tóuwèi","먹이를 주다"]],"tr":["사람의 뇌 무게는 체중의 약 2%에 불과하지만, 쓰는 에너지는 온몸이 쓰는 양의 약 20%를 차지한다.","우리나라 옛 과거 제도는 수나라 때 시작되어 청나라 말에야 폐지되었으니, 1,300여 년 동안 이어졌다.","아무리 재능이 넘쳐도 남과 협력하려는 마음이 없으면, 팀 안에서 제 역할을 제대로 해내기 어렵다.","희귀종을 보호하기 위해 관광지 관리소는 자연보호구역 핵심 구역에서 관광객이 함부로 야생 동물에게 먹이를 주는 것을 엄격히 금한다고 분명히 규정했다."],"ow":[[["大脑","dànǎo","대뇌, 뇌"],["消耗","xiāohào","소모하다"]],[["科举","kējǔ","과거 제도"],["隋朝","Suí cháo","수나라"],["废除","fèichú","폐지하다"],["延续","yánxù","이어지다"]],[["才华横溢","cái huá héng yì","재능이 넘치다"],["缺乏","quēfá","부족하다"],["团队","tuánduì","팀"]],[["珍稀","zhēnxī","진귀하고 드물다"],["物种","wùzhǒng","생물 종"],["严禁","yánjìn","엄금하다"],["投喂","tóuwèi","먹이를 주다"]]]},{"o":["蝙蝠能够发出人耳听不到的超声波，并根据回声判断障碍物和猎物的位置，这就是“回声定位”。","经过技术改造，这条生产线每吨产品的能耗降低了两倍，生产效率则提高了近一半。","洛阳自东周起先后有十三个王朝在此建都，因而有“十三朝古都”之称。","与其花大量时间抱怨环境的不公，倒不如静下心来想一想自己还能做些什么。"],"a":1,"type":"배수 감소","why":"줄어드는 것은 “降低了两倍”처럼 배수로 말할 수 없다. 분수(一半, 三分之二)로 말해야 한다.","fix":"经过技术改造，这条生产线每吨产品的能耗降低了一半，生产效率则提高了近一半。","words":[["超声波","chāoshēngbō","초음파"],["回声定位","huíshēng dìngwèi","반향 위치 측정"],["改造","gǎizào","개조하다"],["能耗","nénghào","에너지 소모"],["建都","jiàndū","도읍을 정하다"],["抱怨","bàoyuàn","불평하다"]],"tr":["박쥐는 사람 귀에 들리지 않는 초음파를 내고 그 메아리로 장애물과 먹잇감의 위치를 가늠하는데, 이것이 바로 ‘반향 위치 측정’이다.","기술 개조를 거쳐 이 생산 라인은 제품 1톤당 에너지 소모가 두 배나 줄었고, 생산 효율은 절반 가까이 높아졌다.","뤄양에는 동주 때부터 열세 왕조가 차례로 도읍을 정해 ‘열세 왕조의 옛 수도’라 불린다.","환경이 불공평하다고 불평하며 많은 시간을 쓰기보다는, 차분히 자신이 무엇을 더 할 수 있는지 생각해 보는 편이 낫다."],"ow":[[["蝙蝠","biānfú","박쥐"],["超声波","chāoshēngbō","초음파"],["障碍物","zhàng'àiwù","장애물"],["猎物","lièwù","먹잇감"],["回声定位","huíshēng dìngwèi","반향 위치 측정"]],[["改造","gǎizào","개조하다"],["生产线","shēngchǎnxiàn","생산 라인"],["能耗","nénghào","에너지 소모"]],[["洛阳","Luòyáng","뤄양"],["东周","Dōng Zhōu","동주"],["王朝","wángcháo","왕조"],["建都","jiàndū","도읍을 정하다"]],[["与其","yǔqí","~하기보다는"],["抱怨","bàoyuàn","불평하다"],["不公","bùgōng","불공평하다"]]]},{"o":["“丝绸之路”这一名称，其实是十九世纪德国地理学家李希霍芬首先提出的。","青少年正处在身体发育的关键时期，每天保证充足的睡眠和适量的运动尤为重要。","与上一代产品相比，这款新型存储芯片的体积缩小了五倍，存储容量却增加了一倍。","这座城市三面环山、一面临海，冬无严寒、夏无酷暑，是不少人心目中理想的宜居之地。"],"a":2,"type":"배수 감소","why":"“缩小了五倍”처럼 줄어드는 것을 배수로 말할 수 없다. “缩小到原来的五分之一”로 써야 한다. 늘어나는 “增加了一倍”는 맞다.","fix":"与上一代产品相比，这款新型存储芯片的体积缩小到原来的五分之一，存储容量却增加了一倍。","words":[["李希霍芬","Lǐxīhuòfēn","리히트호펜"],["发育","fāyù","발육"],["存储","cúnchǔ","저장"],["芯片","xīnpiàn","칩"],["三面环山","sān miàn huán shān","삼면이 산으로 둘러싸이다"],["宜居","yíjū","살기 좋다"]],"tr":["‘실크로드’라는 이름은 사실 19세기 독일 지리학자 리히트호펜이 처음 붙인 것이다.","청소년은 몸이 자라는 중요한 시기에 있으므로, 날마다 잠을 넉넉히 자고 알맞게 운동하는 것이 특히 중요하다.","이전 세대 제품과 비교해 이 새 저장 칩은 부피가 다섯 배 작아졌지만 저장 용량은 두 배로 늘었다.","이 도시는 삼면이 산이고 한쪽이 바다에 닿아 있어 겨울에 혹한이 없고 여름에 무더위가 없으니, 많은 사람이 살기 좋은 곳으로 여긴다."],"ow":[[["丝绸之路","Sīchóu zhī Lù","실크로드"],["地理学家","dìlǐxuéjiā","지리학자"],["李希霍芬","Lǐxīhuòfēn","리히트호펜"]],[["发育","fāyù","발육"],["充足","chōngzú","충분하다"],["尤为","yóuwéi","특히"]],[["存储","cúnchǔ","저장"],["芯片","xīnpiàn","칩"],["体积","tǐjī","부피"],["容量","róngliàng","용량"]],[["三面环山","sān miàn huán shān","삼면이 산으로 둘러싸이다"],["严寒","yánhán","혹한"],["酷暑","kùshǔ","무더위"],["宜居","yíjū","살기 좋다"]]]},{"o":["这家科技馆的展品涵盖了天文、物理、化学、生物以及自然科学等多个领域，每年吸引数十万名中小学生前来参观。","金刚石和石墨虽然外观和硬度相差极大，但它们都是由碳元素构成的单质。","在古代，人们常用烽火台传递军情，一旦发现敌情，便白天放烟、夜间举火。","为了缩短配送时间，不少零售企业在城市周边建起了前置仓，把常用商品提前存放在离消费者更近的地方。"],"a":0,"type":"범위·분류","why":"“自然科学”는 천문·물리·화학·생물을 모두 포함하는 큰 범주인데 이들과 나란히 늘어놓았다.","fix":"这家科技馆的展品涵盖了天文、物理、化学、生物等多个自然科学领域，每年吸引数十万名中小学生前来参观。","words":[["涵盖","hángài","포괄하다"],["金刚石","jīngāngshí","다이아몬드"],["石墨","shímò","흑연"],["单质","dānzhì","홑원소 물질"],["烽火台","fēnghuǒtái","봉화대"],["前置仓","qiánzhìcāng","소비지 근처 소형 창고"],["配送","pèisòng","배송"]],"tr":["이 과학관의 전시품은 천문, 물리, 화학, 생물 그리고 자연과학 등 여러 분야에 걸쳐 있으며, 해마다 수십만 명의 초중고생이 찾아온다.","다이아몬드와 흑연은 겉모습과 단단함이 크게 다르지만, 둘 다 탄소 원소로만 이루어진 홑원소 물질이다.","옛날에는 봉화대로 군사 소식을 전했는데, 적이 보이면 낮에는 연기를 피우고 밤에는 불을 올렸다.","배송 시간을 줄이려고 많은 소매 기업이 도시 주변에 소형 전진 창고를 지어, 자주 팔리는 상품을 소비자와 더 가까운 곳에 미리 보관해 둔다."],"ow":[[["涵盖","hángài","포괄하다"],["天文","tiānwén","천문"],["自然科学","zìrán kēxué","자연과학"]],[["金刚石","jīngāngshí","다이아몬드"],["石墨","shímò","흑연"],["硬度","yìngdù","경도"],["单质","dānzhì","홑원소 물질"]],[["烽火台","fēnghuǒtái","봉화대"],["军情","jūnqíng","군사 정세"],["敌情","díqíng","적의 동태"]],[["配送","pèisòng","배송"],["零售","língshòu","소매"],["前置仓","qiánzhìcāng","소비지 근처 소형 창고"],["存放","cúnfàng","보관하다"]]]},{"o":["声带振动发出的声音经过口腔、鼻腔等部位的共鸣，才形成了每个人独特的嗓音。","近年来，浙江、江苏、广东和深圳等省份大力发展数字经济，涌现出了一批具有国际竞争力的科技企业。","在一些制造业发达的城市，技术过硬的高级焊工月薪甚至超过了不少写字楼里的白领。","由于连日暴雨，这条通往山区的公路多处出现塌方，抢修工作预计需要一周左右才能完成。"],"a":1,"type":"범위·분류","why":"“深圳”은 도시(광둥성 안에 있음)인데 “省份”(성) 목록에 함께 넣었다.","fix":"近年来，浙江、江苏、广东等省份大力发展数字经济，涌现出了一批具有国际竞争力的科技企业。","words":[["声带","shēngdài","성대"],["共鸣","gòngmíng","공명"],["涌现","yǒngxiàn","대거 나타나다"],["塌方","tāfāng","(토사) 붕괴"],["抢修","qiǎngxiū","긴급 복구하다"],["过硬","guòyìng","실력이 탄탄하다"],["焊工","hàngōng","용접공"]],"tr":["성대가 떨려 나는 소리는 입안과 콧속 등의 공명을 거쳐야 비로소 사람마다 다른 목소리가 된다.","최근 저장, 장쑤, 광둥, 선전 등의 성에서는 디지털 경제를 힘껏 키워, 국제 경쟁력을 갖춘 과학 기술 기업들이 잇따라 나타났다.","제조업이 발달한 일부 도시에서는 실력이 탄탄한 고급 용접공의 월급이 사무실의 많은 화이트칼라보다 높기까지 하다.","며칠째 이어진 폭우로 산간 지역으로 가는 이 도로 곳곳이 무너져, 긴급 복구에 일주일쯤 걸릴 것으로 보인다."],"ow":[[["声带","shēngdài","성대"],["振动","zhèndòng","진동하다"],["鼻腔","bíqiāng","콧속"],["共鸣","gòngmíng","공명"],["嗓音","sǎngyīn","목소리"]],[["深圳","Shēnzhèn","선전"],["数字经济","shùzì jīngjì","디지털 경제"],["涌现","yǒngxiàn","대거 나타나다"],["竞争力","jìngzhēnglì","경쟁력"]],[["制造业","zhìzàoyè","제조업"],["过硬","guòyìng","실력이 탄탄하다"],["焊工","hàngōng","용접공"],["写字楼","xiězìlóu","사무용 빌딩"],["白领","báilǐng","화이트칼라"]],[["连日","liánrì","며칠째"],["塌方","tāfāng","(토사) 붕괴"],["抢修","qiǎngxiū","긴급 복구하다"]]]},{"o":["牛顿和莱布尼茨几乎在同一时期各自独立地创立了微积分，两人之间还曾为此发生过激烈的优先权之争。","豆腐相传是西汉淮南王刘安在炼丹时偶然发明的，至今已有两千多年的历史。","越来越多的年轻人利用业余时间学习传统手工艺，这让一些面临失传的技艺重新焕发了生机。","经过近半年的综合整治，这片湖泊中泛滥成灾的蓝藻几乎已被彻底清除干净，湖水重新变得清澈见底。"],"a":3,"type":"자기모순","why":"“几乎”(거의)와 “彻底…干净”(완전히 깨끗이)이 함께 쓰여 ‘거의’인지 ‘완전히’인지 앞뒤가 모순된다.","fix":"经过近半年的综合整治，这片湖泊中泛滥成灾的蓝藻已被彻底清除干净，湖水重新变得清澈见底。","words":[["微积分","wēijīfēn","미적분"],["优先权","yōuxiānquán","우선권"],["炼丹","liàndān","단약을 만들다"],["焕发","huànfā","빛을 발하다"],["泛滥成灾","fàn làn chéng zāi","넘쳐 재해가 되다"],["蓝藻","lánzǎo","남조류"]],"tr":["뉴턴과 라이프니츠는 거의 같은 시기에 각자 미적분을 세웠고, 둘 사이에는 이를 두고 누가 먼저냐는 치열한 다툼까지 있었다.","두부는 서한 회남왕 유안이 단약을 만들다가 우연히 발명했다고 전해지며, 지금까지 2천여 년의 역사를 지녔다.","여가 시간에 전통 수공예를 배우는 젊은이가 늘면서, 전승이 끊길 위기에 놓였던 일부 기술이 다시 생기를 되찾았다.","반년 가까운 종합 정비 끝에 이 호수에 넘쳐 나던 남조류가 거의 깨끗이 없어져, 호수가 다시 바닥이 보일 만큼 맑아졌다."],"ow":[[["莱布尼茨","Láibùnící","라이프니츠"],["微积分","wēijīfēn","미적분"],["优先权","yōuxiānquán","우선권"]],[["豆腐","dòufu","두부"],["淮南王","Huáinán wáng","회남왕"],["刘安","Liú Ān","유안"],["炼丹","liàndān","단약을 만들다"]],[["手工艺","shǒugōngyì","수공예"],["失传","shīchuán","전승이 끊기다"],["焕发","huànfā","빛을 발하다"],["生机","shēngjī","생기"]],[["整治","zhěngzhì","정비하다"],["泛滥成灾","fàn làn chéng zāi","넘쳐 재해가 되다"],["蓝藻","lánzǎo","남조류"],["清澈见底","qīng chè jiàn dǐ","바닥이 보일 만큼 맑다"]]]},{"o":["气象专家根据最新的卫星云图分析认为，今年第九号台风肯定大约会在明天凌晨于沿海地区登陆。","这座港口的自动化码头实现了远程操控，桥吊司机坐在控制室里就能完成集装箱的装卸作业。","凭借一双巧手，这位高级钳工打磨出的零件，误差常常不到头发丝直径的十分之一。","他从事乡村教育工作三十余年，培养的学生中，有的成了科学家，有的回到家乡当了老师。"],"a":0,"type":"자기모순","why":"“肯定”(틀림없이)과 “大约”(아마, 대략)가 함께 쓰여 확실한지 아닌지가 모순된다.","fix":"气象专家根据最新的卫星云图分析认为，今年第九号台风大约会在明天凌晨于沿海地区登陆。","words":[["卫星云图","wèixīng yúntú","위성 구름 사진"],["登陆","dēnglù","(태풍이) 상륙하다"],["桥吊","qiáodiào","갠트리 크레인"],["集装箱","jízhuāngxiāng","컨테이너"],["装卸","zhuāngxiè","싣고 내리다"],["钳工","qiángōng","정밀 가공 기술자"],["打磨","dǎmó","연마하다"]],"tr":["기상 전문가들은 최신 위성 구름 사진을 분석해, 올해 9호 태풍이 틀림없이 내일 새벽 무렵 해안 지역에 상륙할 것으로 보았다.","이 항구의 자동화 부두는 원격 조종이 가능해, 크레인 기사가 통제실에 앉아서도 컨테이너를 싣고 내릴 수 있다.","뛰어난 손재주를 지닌 이 고급 정밀 가공 기술자가 다듬은 부품은 오차가 머리카락 굵기의 10분의 1도 안 될 때가 많다.","그는 30여 년 동안 농촌 교육에 몸담았고, 그가 길러 낸 학생 중에는 과학자가 된 이도 있고 고향에 돌아가 교사가 된 이도 있다."],"ow":[[["气象","qìxiàng","기상"],["卫星云图","wèixīng yúntú","위성 구름 사진"],["凌晨","língchén","새벽"],["登陆","dēnglù","(태풍이) 상륙하다"]],[["码头","mǎtou","부두"],["远程","yuǎnchéng","원격"],["桥吊","qiáodiào","갠트리 크레인"],["集装箱","jízhuāngxiāng","컨테이너"],["装卸","zhuāngxiè","싣고 내리다"]],[["凭借","píngjiè","~에 기대어"],["钳工","qiángōng","정밀 가공 기술자"],["打磨","dǎmó","연마하다"],["误差","wùchā","오차"],["直径","zhíjìng","지름"]],[["从事","cóngshì","종사하다"],["乡村","xiāngcūn","농촌"]]]},{"o":["冰川是地球上最大的淡水资源库，储存着全球约百分之七十的淡水。","人们常用“桃李满天下”来形容一位老师培养的学生众多、遍布各地，表达对教师辛勤付出的赞美。","尽管智能手机的功能日益强大，但对于不少老年人来说，熟练使用各种应用程序仍然是一件颇为困难的事。","这次科普知识竞赛共有一百二十名学生参加，其中初中生七十五人，高中生五十五人，最终有二十人进入决赛。"],"a":3,"type":"자기모순","why":"참가자가 모두 120명이라 했는데 중학생 75명과 고등학생 55명을 더하면 130명이라 숫자가 맞지 않는다.","fix":"这次科普知识竞赛共有一百二十名学生参加，其中初中生七十五人，高中生四十五人，最终有二十人进入决赛。","words":[["冰川","bīngchuān","빙하"],["淡水","dànshuǐ","담수"],["桃李满天下","táo lǐ mǎn tiān xià","제자가 온 세상에 가득하다"],["日益","rìyì","날로"],["颇为","pōwéi","꽤"],["决赛","juésài","결승"]],"tr":["빙하는 지구에서 가장 큰 담수 저장고로, 전 세계 담수의 약 70%를 품고 있다.","사람들은 흔히 ‘복숭아와 자두가 천하에 가득하다’는 말로 한 스승이 길러 낸 제자가 많고 곳곳에 퍼져 있음을 나타내며, 스승의 노고를 기린다.","스마트폰 기능은 날로 강력해지지만, 적잖은 노인에게 여러 앱을 능숙하게 쓰는 일은 여전히 꽤 어렵다.","이번 과학 상식 대회에는 학생 120명이 참가했는데, 그중 중학생이 75명, 고등학생이 55명이었고 마지막에 20명이 결승에 올랐다."],"ow":[[["冰川","bīngchuān","빙하"],["淡水","dànshuǐ","담수"],["储存","chǔcún","저장하다"]],[["桃李满天下","táo lǐ mǎn tiān xià","제자가 온 세상에 가득하다"],["遍布","biànbù","널리 퍼지다"],["辛勤","xīnqín","부지런하다"]],[["日益","rìyì","날로"],["熟练","shúliàn","능숙하다"],["应用程序","yìngyòng chéngxù","앱"],["颇为","pōwéi","꽤"]],[["科普","kēpǔ","과학 보급"],["竞赛","jìngsài","대회"],["决赛","juésài","결승"]]]}],[{"o":["黑洞并不是真正的“洞”，而是一种引力极强、连光都无法从中逃脱的特殊天体。","专家调查后指出，这片珊瑚礁大面积白化的主要原因，是海水温度持续异常升高所造成的。","中国古代的“四书”指的是《大学》《中庸》《论语》和《孟子》，它们是明清科举考试的主要内容。","这家初创公司能在短时间内赢得市场，在很大程度上得益于其对用户需求的精准把握。"],"a":1,"type":"구식 혼합","why":"“原因是…”와 “是…造成的” 두 구조가 섞였다. 원인이 ‘…로 인해 생긴 것’이 되어 버렸다.","fix":"专家调查后指出，这片珊瑚礁大面积白化的主要原因，是海水温度持续异常升高。","words":[["黑洞","hēidòng","블랙홀"],["天体","tiāntǐ","천체"],["白化","báihuà","(산호의) 백화"],["中庸","Zhōngyōng","중용"],["初创","chūchuàng","창업 초기의"],["把握","bǎwò","파악"]],"tr":["블랙홀은 진짜 ‘구멍’이 아니라 인력이 매우 강해 빛조차 빠져나오지 못하는 특별한 천체다.","전문가들은 조사 끝에 이 산호초가 넓게 하얗게 변한 주된 원인은 바닷물 온도가 계속 비정상적으로 오른 탓이라고 지적했다.","중국 옛 ‘사서’는 「대학」 「중용」 「논어」 「맹자」를 가리키며, 명청 시대 과거 시험의 주된 내용이었다.","이 신생 기업이 짧은 시간에 시장을 잡은 것은 상당 부분 사용자 요구를 정확히 파악한 덕분이다."],"ow":[[["黑洞","hēidòng","블랙홀"],["引力","yǐnlì","인력"],["逃脱","táotuō","빠져나가다"],["天体","tiāntǐ","천체"]],[["珊瑚礁","shānhújiāo","산호초"],["白化","báihuà","(산호의) 백화"],["异常","yìcháng","비정상적으로"]],[["四书","Sìshū","사서"],["中庸","Zhōngyōng","중용"],["论语","Lúnyǔ","논어"],["孟子","Mèngzǐ","맹자"],["科举","kējǔ","과거 제도"]],[["初创","chūchuàng","창업 초기의"],["得益于","déyì yú","~덕분이다"],["精准","jīngzhǔn","정확하다"],["把握","bǎwò","파악"]]]},{"o":["光年是长度单位而不是时间单位，指的是光在真空中一年内传播的距离。","相声讲究“说、学、逗、唱”四门功课，是一门深受北方观众喜爱的曲艺艺术。","研究发现，人们在做出重要决定之前适当拖延一段时间，有时反而能够得出更加理性的判断。","这一地区地处干旱的戈壁边缘，农业生产主要是靠祁连山的冰雪融水灌溉为主。"],"a":3,"type":"구식 혼합","why":"“主要靠…灌溉”와 “以…灌溉为主” 두 구조가 섞였다.","fix":"这一地区地处干旱的戈壁边缘，农业生产主要靠祁连山的冰雪融水灌溉。","words":[["光年","guāngnián","광년"],["相声","xiàngsheng","만담"],["曲艺","qǔyì","설창 예술"],["拖延","tuōyán","미루다"],["戈壁","gēbì","고비 사막(자갈 사막)"],["祁连山","Qílián Shān","기련산"],["灌溉","guàngài","관개하다"]],"tr":["광년은 시간 단위가 아니라 길이 단위로, 빛이 진공에서 1년 동안 가는 거리를 말한다.","만담은 ‘말하기, 흉내 내기, 웃기기, 노래하기’ 네 가지 기본기를 중시하며, 북방 관객이 매우 사랑하는 설창 예술이다.","연구에 따르면 중요한 결정을 내리기 전에 시간을 적당히 미루면 오히려 더 이성적인 판단을 내릴 때가 있다.","이 지역은 메마른 고비 사막 가장자리에 있어, 농사는 주로 기련산의 눈과 얼음이 녹은 물로 물을 대는 데 의지한다."],"ow":[[["光年","guāngnián","광년"],["真空","zhēnkōng","진공"]],[["相声","xiàngsheng","만담"],["讲究","jiǎngjiu","중시하다"],["曲艺","qǔyì","설창 예술"]],[["拖延","tuōyán","미루다"],["理性","lǐxìng","이성적"]],[["戈壁","gēbì","고비 사막(자갈 사막)"],["祁连山","Qílián Shān","기련산"],["融水","róngshuǐ","녹은 물"],["灌溉","guàngài","관개하다"]]]},{"o":["一项科研成果要成功转化为市场上的产品，关键在于企业与高校之间的合作机制起着决定性的作用。","印刷术传入欧洲后，书籍的价格大幅下降，知识不再是少数贵族和教士的专利。","川金丝猴是我国特有的珍贵灵长类动物，主要分布在四川、陕西、甘肃、湖北等地的高山密林中。","越是在艰难的时刻，越需要保持清醒的头脑，千万不能因一时的挫折而自乱阵脚。"],"a":0,"type":"구식 혼합","why":"“关键在于…”와 “…起着决定性的作用” 두 구조가 섞였다.","fix":"一项科研成果要成功转化为市场上的产品，关键在于企业与高校之间的合作机制。","words":[["转化","zhuǎnhuà","전환하다"],["机制","jīzhì","체계, 메커니즘"],["教士","jiàoshì","성직자"],["专利","zhuānlì","전유물"],["灵长类","língzhǎnglèi","영장류"],["自乱阵脚","zì luàn zhèn jiǎo","스스로 흔들리다"]],"tr":["연구 성과가 시장의 제품으로 성공적으로 바뀌려면, 기업과 대학 사이의 협력 체계가 결정적인 역할을 한다는 점이 관건이다.","인쇄술이 유럽에 전해진 뒤 책값이 크게 떨어져, 지식은 더 이상 소수 귀족과 성직자의 전유물이 아니게 되었다.","쓰촨들창코원숭이는 우리나라에만 사는 귀한 영장류로, 주로 쓰촨, 산시, 간쑤, 후베이 등지의 높은 산 울창한 숲에 산다.","힘든 때일수록 머리를 맑게 유지해야 하며, 한때의 좌절 때문에 스스로 흔들려서는 절대 안 된다."],"ow":[[["科研","kēyán","과학 연구"],["转化","zhuǎnhuà","전환하다"],["高校","gāoxiào","대학"],["机制","jīzhì","체계, 메커니즘"]],[["印刷术","yìnshuāshù","인쇄술"],["贵族","guìzú","귀족"],["教士","jiàoshì","성직자"],["专利","zhuānlì","전유물"]],[["川金丝猴","chuān jīnsīhóu","쓰촨들창코원숭이"],["特有","tèyǒu","고유하다"],["灵长类","língzhǎnglèi","영장류"],["密林","mìlín","울창한 숲"]],[["清醒","qīngxǐng","맑다, 깨어 있다"],["挫折","cuòzhé","좌절"],["自乱阵脚","zì luàn zhèn jiǎo","스스로 흔들리다"]]]},{"o":["电子显微镜利用电子束代替可见光成像，其分辨率比普通光学显微镜高出上千倍。","苏轼不仅是北宋著名的文学家，在书法上也颇有造诣，与黄庭坚、米芾、蔡襄并称“宋四家”。","草原沙化日益严重，在很大程度上是长期过度放牧和滥采滥挖的结果所致。","每个人都难免有情绪低落的时候，关键是要学会找到适合自己的方式来调节。"],"a":2,"type":"구식 혼합","why":"“是…的结果”와 “…所致”(~로 인한 것) 두 구조가 섞였다.","fix":"草原沙化日益严重，在很大程度上是长期过度放牧和滥采滥挖的结果。","words":[["分辨率","fēnbiànlǜ","해상도"],["造诣","zàoyì","조예"],["米芾","Mǐ Fú","미불(북송 서예가)"],["沙化","shāhuà","사막화"],["放牧","fàngmù","방목하다"],["所致","suǒzhì","~로 인한 것"]],"tr":["전자 현미경은 보이는 빛 대신 전자빔으로 상을 맺어, 해상도가 일반 광학 현미경보다 천 배 넘게 높다.","소식은 북송의 이름난 문학가일 뿐 아니라 서예에도 조예가 깊어, 황정견, 미불, 채양과 함께 ‘송사가’로 불린다.","초원의 사막화가 날로 심해지는 것은 상당 부분 오랜 과잉 방목과 마구잡이 채취로 인한 결과다.","누구나 기분이 가라앉을 때가 있기 마련이며, 중요한 것은 자신에게 맞는 방법을 찾아 마음을 다스리는 것이다."],"ow":[[["显微镜","xiǎnwēijìng","현미경"],["电子束","diànzǐshù","전자빔"],["成像","chéngxiàng","상을 맺다"],["分辨率","fēnbiànlǜ","해상도"]],[["苏轼","Sū Shì","소식(소동파)"],["造诣","zàoyì","조예"],["黄庭坚","Huáng Tíngjiān","황정견"],["米芾","Mǐ Fú","미불"],["蔡襄","Cài Xiāng","채양"]],[["沙化","shāhuà","사막화"],["日益","rìyì","날로"],["放牧","fàngmù","방목하다"],["滥采滥挖","làn cǎi làn wā","마구 캐고 파다"],["所致","suǒzhì","~로 인한 것"]],[["难免","nánmiǎn","~하기 마련이다"],["低落","dīluò","가라앉다"],["调节","tiáojié","조절하다"]]]},{"o":["恒星的颜色与其表面温度密切相关：温度越高，颜色越偏蓝；温度越低，颜色越偏红。","这本关于古代建筑的科普读物图文并茂、深入浅出，不仅适合专业人士，也适合普通读者阅读。","他退休后才开始学习绘画，没想到几年下来竟画出了名堂，还举办了个人画展。","自从这座跨海大桥正式通车以来，使两岸之间的车程从原来的三个多小时缩短到了四十分钟。"],"a":3,"type":"주어 결여","why":"“自从…以来，使…” 때문에 주어가 없다. 使를 빼야 车程이 주어가 된다.","fix":"自从这座跨海大桥正式通车以来，两岸之间的车程从原来的三个多小时缩短到了四十分钟。","words":[["偏蓝","piānlán","푸른빛을 띠다"],["图文并茂","tú wén bìng mào","그림과 글이 모두 훌륭하다"],["深入浅出","shēn rù qiǎn chū","깊은 내용을 쉽게 풀다"],["名堂","míngtang","성과"],["跨海大桥","kuàhǎi dàqiáo","바다를 건너는 다리"],["通车","tōngchē","개통하다"]],"tr":["항성의 색은 표면 온도와 밀접한 관계가 있다. 온도가 높을수록 푸른빛을 띠고, 낮을수록 붉은빛을 띤다.","옛 건축을 다룬 이 과학 교양서는 그림과 글이 모두 알차고 깊은 내용을 쉽게 풀어내, 전문가뿐 아니라 일반 독자가 읽기에도 알맞다.","그는 은퇴하고서야 그림을 배우기 시작했는데, 몇 년 만에 뜻밖에도 성과를 내어 개인전까지 열었다.","이 바다를 건너는 큰 다리가 정식 개통된 뒤로, 양쪽 사이 차로 가는 시간이 세 시간 넘게 걸리던 것에서 40분으로 줄었다."],"ow":[[["恒星","héngxīng","항성"],["密切","mìqiè","밀접하다"],["偏蓝","piān lán","푸른빛을 띠다"]],[["科普读物","kēpǔ dúwù","과학 교양서"],["图文并茂","tú wén bìng mào","그림과 글이 모두 훌륭하다"],["深入浅出","shēn rù qiǎn chū","깊은 내용을 쉽게 풀다"]],[["退休","tuìxiū","은퇴하다"],["名堂","míngtang","성과"],["画展","huàzhǎn","미술 전시회"]],[["跨海大桥","kuàhǎi dàqiáo","바다를 건너는 다리"],["通车","tōngchē","개통하다"],["车程","chēchéng","차로 가는 거리·시간"],["缩短","suōduǎn","단축하다"]]]},{"o":["研究人员发现，这种深海鱼类之所以能在高压环境中生存，是因为其细胞内含有一种能够稳定蛋白质结构的特殊物质。","这次展览通过大量珍贵的文物和翔实的史料，生动地再现了古代海上丝绸之路的繁荣景象和重要地位。","在众多古典乐器中，古琴因音色深沉悠远而为文人雅士所钟爱，位列“琴棋书画”四艺之首。","父母的言行举止对孩子有着潜移默化的影响，因此家长应当时时处处为孩子做出表率。"],"a":1,"type":"목적어 여럿 중 일부","why":"“再现”(다시 보여 주다)은 “景象”(광경)과는 맞지만 “地位”(위상)와는 맞지 않는다. 위상은 “展示”하거나 “说明”한다.","fix":"这次展览通过大量珍贵的文物和翔实的史料，生动地再现了古代海上丝绸之路的繁荣景象，展示了它的重要地位。","words":[["蛋白质","dànbáizhì","단백질"],["翔实","xiángshí","상세하고 확실하다"],["再现","zàixiàn","재현하다"],["古琴","gǔqín","고금(현악기)"],["钟爱","zhōng'ài","아끼고 사랑하다"],["潜移默化","qián yí mò huà","은연중에 감화하다"],["表率","biǎoshuài","본보기"]],"tr":["연구진은 이 심해어가 높은 압력에서 살 수 있는 것은 세포 속에 단백질 구조를 안정시키는 특별한 물질이 있기 때문이라는 것을 발견했다.","이번 전시는 많은 귀한 유물과 자세한 사료로 옛 해상 실크로드의 번영한 모습과 중요한 위상을 생생하게 되살려 냈다.","여러 고전 악기 가운데 고금은 소리가 깊고 그윽하여 문인과 선비들의 사랑을 받았고, ‘금기서화’ 네 가지 기예 중 으뜸으로 꼽힌다.","부모의 말과 행동은 아이에게 은연중에 영향을 주므로, 부모는 언제 어디서나 아이에게 본보기가 되어야 한다."],"ow":[[["深海","shēnhǎi","심해"],["之所以","zhīsuǒyǐ","~한 까닭은"],["细胞","xìbāo","세포"],["蛋白质","dànbáizhì","단백질"]],[["文物","wénwù","문화재, 유물"],["翔实","xiángshí","상세하고 확실하다"],["史料","shǐliào","사료"],["再现","zàixiàn","재현하다"],["繁荣","fánróng","번영하다"]],[["古琴","gǔqín","고금(현악기)"],["悠远","yōuyuǎn","그윽하고 멀다"],["文人雅士","wén rén yǎ shì","문인과 선비"],["钟爱","zhōng'ài","아끼고 사랑하다"],["琴棋书画","qín qí shū huà","거문고·바둑·서예·그림"]],[["言行举止","yán xíng jǔ zhǐ","말과 행동"],["潜移默化","qián yí mò huà","은연중에 감화하다"],["表率","biǎoshuài","본보기"]]]},{"o":["初次进入海拔四千米以上地区的游客，由于身体尚未适应缺氧环境，难免不会出现头痛、胸闷等高原反应。","地球上的四季变化，主要是由地球公转时地轴相对于公转轨道面保持倾斜造成的。","京杭大运河北起北京，南至杭州，全长一千七百九十多千米，是世界上里程最长的古代运河。","一个城市的文化品位，不仅体现在宏伟的建筑上，更体现在市民日常的言谈举止之中。"],"a":0,"type":"이중 부정","why":"“难免”(~하기 마련이다)에 “不会”를 붙여 ‘고산병이 안 생기기 마련이다’라는 반대 뜻이 되었다.","fix":"初次进入海拔四千米以上地区的游客，由于身体尚未适应缺氧环境，难免会出现头痛、胸闷等高原反应。","words":[["缺氧","quēyǎng","산소 부족"],["难免","nánmiǎn","~하기 마련이다"],["公转","gōngzhuàn","공전"],["地轴","dìzhóu","지축"],["运河","yùnhé","운하"],["品位","pǐnwèi","품격"],["言谈举止","yán tán jǔ zhǐ","말과 행동"]],"tr":["해발 4천 미터가 넘는 지역에 처음 간 관광객은 몸이 아직 산소가 부족한 환경에 익숙하지 않아, 두통이나 가슴 답답함 같은 고산 반응이 생기기 마련이다.","지구의 사계절 변화는 주로 지구가 공전할 때 지축이 공전 궤도면에 대해 기울어진 채로 있기 때문에 생긴다.","징항 대운하는 북으로 베이징, 남으로 항저우에 이르며 길이가 1,790여 킬로미터로, 세계에서 가장 긴 옛 운하다.","한 도시의 문화적 품격은 웅장한 건물에서만이 아니라, 시민들이 날마다 주고받는 말과 행동에서 더 잘 드러난다."],"ow":[[["海拔","hǎibá","해발"],["缺氧","quēyǎng","산소 부족"],["难免","nánmiǎn","~하기 마련이다"],["胸闷","xiōngmèn","가슴이 답답하다"]],[["公转","gōngzhuàn","공전"],["地轴","dìzhóu","지축"],["轨道","guǐdào","궤도"],["倾斜","qīngxié","기울다"]],[["京杭大运河","Jīng-Háng Dàyùnhé","징항 대운하"],["里程","lǐchéng","거리"],["运河","yùnhé","운하"]],[["品位","pǐnwèi","품격"],["宏伟","hóngwěi","웅장하다"],["言谈举止","yán tán jǔ zhǐ","말과 행동"]]]},{"o":["牙齿表面的釉质是人体中最坚硬的组织，但它一旦受损就无法自行再生。","西汉的张骞两次出使西域，开辟了中原通往西域的道路，史称“张骞凿空”。","尽管海况多么恶劣，这艘科考船都会按计划驶往南极冰架附近海域，开展为期两个月的观测。","随着自动化程度不断提高，工厂对普通操作工的需求逐渐减少，对设备维护人员的要求却越来越高。"],"a":2,"type":"짝 오류","why":"“多么…都”처럼 조건을 가리지 않는 말은 “无论”과 짝을 이루는데 “尽管”을 썼다.","fix":"无论海况多么恶劣，这艘科考船都会按计划驶往南极冰架附近海域，开展为期两个月的观测。","words":[["釉质","yòuzhì","(치아) 법랑질"],["再生","zàishēng","재생하다"],["张骞","Zhāng Qiān","장건"],["凿空","záokōng","(길을) 처음 개척하다"],["冰架","bīngjià","빙붕"],["维护","wéihù","유지 보수하다"]],"tr":["치아 표면의 법랑질은 몸에서 가장 단단한 조직이지만, 한번 손상되면 스스로 다시 자라지 못한다.","서한의 장건은 두 차례 서역에 사신으로 가서 중원에서 서역으로 통하는 길을 열었는데, 역사에서는 이를 ‘장건의 길 개척’이라 부른다.","바다 상황이 아무리 나빠도 이 과학 조사선은 계획대로 남극 빙붕 근처 바다로 가서 두 달 동안 관측을 할 것이다.","자동화 수준이 계속 높아지면서 공장에서는 일반 조작공 수요가 줄고, 설비 유지 보수 인력에 대한 요구는 오히려 갈수록 높아지고 있다."],"ow":[[["釉质","yòuzhì","(치아) 법랑질"],["坚硬","jiānyìng","단단하다"],["受损","shòusǔn","손상되다"],["再生","zàishēng","재생하다"]],[["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["中原","Zhōngyuán","중원"],["凿空","záokōng","(길을) 처음 개척하다"]],[["海况","hǎikuàng","바다 상태"],["恶劣","èliè","열악하다"],["科考船","kēkǎochuán","과학 조사선"],["冰架","bīngjià","빙붕"],["观测","guāncè","관측"]],[["自动化","zìdònghuà","자동화"],["操作工","cāozuògōng","조작공"],["维护","wéihù","유지 보수하다"]]]},{"o":["地震发生时，纵波传播速度较快，横波较慢，因此人们通常先感到上下颠簸，再感到左右摇晃。","专家认为，种子质量的优劣，是保证这一地区粮食连年稳产高产的重要条件。","剪纸艺术题材广泛、寓意吉祥，逢年过节，北方许多地区的人们都有在窗户上贴窗花的习俗。","这位资深记者做事一向严谨，在没有掌握充分的证据之前，他从不轻易对事件下结论。"],"a":1,"type":"양면–한면","why":"“优劣”(좋고 나쁨) 두 쪽을 말해 놓고 “保证…稳产高产”(풍작을 보장한다) 한쪽에만 이었다. 나쁜 종자는 풍작을 보장할 수 없다.","fix":"专家认为，优质的种子，是保证这一地区粮食连年稳产高产的重要条件。","words":[["纵波","zòngbō","종파(P파)"],["横波","héngbō","횡파(S파)"],["颠簸","diānbǒ","위아래로 흔들리다"],["优劣","yōuliè","좋고 나쁨"],["稳产高产","wěn chǎn gāo chǎn","안정된 다수확"],["窗花","chuānghuā","창문에 붙이는 종이 장식"],["严谨","yánjǐn","엄밀하다"]],"tr":["지진이 나면 종파는 빨리 전해지고 횡파는 느려서, 사람들은 보통 먼저 위아래로 흔들림을 느끼고 그다음 좌우 흔들림을 느낀다.","전문가들은 종자 품질의 좋고 나쁨이 이 지역 곡물이 해마다 안정적으로 많이 거두게 하는 중요한 조건이라고 본다.","전지 공예는 소재가 다양하고 상서로운 뜻을 담고 있어, 명절이면 북방 많은 지역 사람들이 창문에 종이 장식을 붙이는 풍습이 있다.","이 베테랑 기자는 늘 일을 엄밀하게 처리해, 충분한 증거를 손에 넣기 전에는 사건에 대해 쉽게 결론을 내리지 않는다."],"ow":[[["纵波","zòngbō","종파"],["横波","héngbō","횡파"],["颠簸","diānbǒ","위아래로 흔들리다"],["摇晃","yáohuàng","흔들리다"]],[["优劣","yōuliè","좋고 나쁨"],["稳产高产","wěn chǎn gāo chǎn","안정된 다수확"]],[["剪纸","jiǎnzhǐ","종이 오리기"],["题材","tícái","소재"],["吉祥","jíxiáng","상서롭다"],["逢年过节","féng nián guò jié","명절 때마다"],["窗花","chuānghuā","창문 종이 장식"]],[["资深","zīshēn","경력이 많다"],["严谨","yánjǐn","엄밀하다"],["证据","zhèngjù","증거"]]]},{"o":["太阳系八大行星中，体积最大的是木星，它的质量是其他七颗行星质量总和的两倍多。","中医“望、闻、问、切”的四诊法，相传是战国时期的名医扁鹊总结出来的。","人们往往对唾手可得的东西不加珍惜，而对求之不得的东西念念不忘。","为了让偏远山区的孩子也能享受到优质的教育资源，当地教育部门通过卫星网络，与城市名校的远程同步课堂。"],"a":3,"type":"술어 결여","why":"“通过卫星网络，与…课堂” 뒤에 “开通了” 같은 동사가 없어서 교육 부서가 무엇을 했는지 빠졌다.","fix":"为了让偏远山区的孩子也能享受到优质的教育资源，当地教育部门通过卫星网络，开通了与城市名校的远程同步课堂。","words":[["木星","mùxīng","목성"],["扁鹊","Biǎn Què","편작(전국시대 명의)"],["唾手可得","tuò shǒu kě dé","손쉽게 얻다"],["求之不得","qiú zhī bù dé","구해도 얻지 못하다"],["念念不忘","niàn niàn bú wàng","늘 잊지 못하다"],["远程","yuǎnchéng","원격"]],"tr":["태양계 여덟 행성 가운데 가장 큰 것은 목성으로, 그 질량은 나머지 일곱 행성의 질량을 모두 더한 것의 두 배가 넘는다.","한의학의 ‘보고, 듣고, 묻고, 맥을 짚는’ 네 가지 진찰법은 전국시대 명의 편작이 정리한 것이라고 전해진다.","사람들은 손쉽게 얻을 수 있는 것은 아낄 줄 모르고, 구해도 얻지 못하는 것은 늘 잊지 못하는 경우가 많다.","외딴 산골 아이들도 질 좋은 교육 자원을 누리게 하려고, 현지 교육 당국은 위성 통신망으로 도시 명문 학교와 원격 동시 수업을 열었다."],"ow":[[["太阳系","tàiyángxì","태양계"],["行星","xíngxīng","행성"],["木星","mùxīng","목성"],["质量","zhìliàng","질량"]],[["中医","zhōngyī","한의학"],["四诊法","sìzhěnfǎ","네 가지 진찰법"],["扁鹊","Biǎn Què","편작"]],[["唾手可得","tuò shǒu kě dé","손쉽게 얻다"],["珍惜","zhēnxī","소중히 여기다"],["求之不得","qiú zhī bù dé","구해도 얻지 못하다"],["念念不忘","niàn niàn bú wàng","늘 잊지 못하다"]],[["偏远","piānyuǎn","외지다"],["优质","yōuzhì","양질의"],["卫星","wèixīng","위성"],["远程","yuǎnchéng","원격"]]]}]];
